export const questions: Question[] = [
  { id: "y2in7-001", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 01", difficulty: "Challenge", questionText: "Use partial fractions to find \\( \\displaystyle\\int \\displaystyle\\frac{4}{x^2 - 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 1 = (x - 1)(x + 1)", explanation: "A difference of squares: \\(a^2 - b^2 = (a - b)(a + b)\\) with \\(a = x\\), \\(b = 1\\). The denominator is now two distinct linear factors, so the partial fraction decomposition takes the form \\(\\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 1}\\)." }, { stepNumber: 2, description: "Set up the decomposition equation.", workingLatex: "\\displaystyle\\frac{4}{(x - 1)(x + 1)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 1} \\;\\Rightarrow\\; 4 = A(x + 1) + B(x - 1)", explanation: "Multiply both sides by \\((x - 1)(x + 1)\\) to clear denominators. The resulting identity must hold for every value of \\(x\\), which gives us a way to pin down \\(A\\) and \\(B\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 1:\\;\\; 4 = 2A \\Rightarrow A = 2; \\quad x = -1:\\;\\; 4 = -2B \\Rightarrow B = -2", explanation: "Substituting the roots of each linear factor zeroes out the other term, isolating one unknown at a time. This is the fastest route for distinct linear factors." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{4}{x^2 - 1} = \\displaystyle\\frac{2}{x - 1} - \\displaystyle\\frac{2}{x + 1}", explanation: "Substitute \\(A = 2\\) and \\(B = -2\\) back in. Each piece is now a standard \\(\\displaystyle\\frac{k}{x - a}\\) form whose antiderivative is a logarithm." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{2}{x - 1} - \\displaystyle\\frac{2}{x + 1} \\right) dx = 2\\ln|x - 1| - 2\\ln|x + 1| + C", explanation: "Using \\(\\displaystyle\\int \\displaystyle\\frac{1}{x - a}\\,dx = \\ln|x - a| + C\\) on each fraction. The constants \\(2\\) and \\(-2\\) pull through the integral." }, { stepNumber: 6, description: "Combine logs using \\(\\ln a - \\ln b = \\ln(a/b)\\).", workingLatex: "2\\ln|x - 1| - 2\\ln|x + 1| = 2\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Factor out the common coefficient \\(2\\), then apply the log-quotient law to present the answer in compact form." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 2\\ln|x - 1| - 2\\ln|x + 1| \\right] = \\displaystyle\\frac{2}{x - 1} - \\displaystyle\\frac{2}{x + 1} = \\displaystyle\\frac{2(x + 1) - 2(x - 1)}{(x - 1)(x + 1)} = \\displaystyle\\frac{4}{x^2 - 1}", explanation: "Differentiating recovers the original integrand, confirming the antiderivative is correct." } ], finalAnswer: "\\(2\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| + C\\)." } },
  // ── Standard two-factor ────
  { id: "y2in7-002", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 02", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x(x + 1)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Note the denominator is already factored.", workingLatex: "x(x + 1) \\;\\;\\text{— two distinct linear factors}", explanation: "Distinct linear factors mean a decomposition of the form \\(\\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1}\\)." }, { stepNumber: 2, description: "Set up the decomposition equation.", workingLatex: "\\displaystyle\\frac{1}{x(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} \\;\\Rightarrow\\; 1 = A(x + 1) + Bx", explanation: "Multiply through by \\(x(x + 1)\\). This identity in \\(x\\) gives us two equations once we pick convenient values." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 0:\\;\\; 1 = A; \\quad x = -1:\\;\\; 1 = -B \\Rightarrow B = -1", explanation: "Substitute the roots of each linear factor in turn to isolate one constant per equation." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{1}{x(x + 1)} = \\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 1}", explanation: "Plug \\(A = 1\\), \\(B = -1\\) back into the template." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 1} \\right) dx = \\ln|x| - \\ln|x + 1| + C = \\ln\\left|\\displaystyle\\frac{x}{x + 1}\\right| + C", explanation: "Each piece integrates to a logarithm via \\(\\displaystyle\\int \\displaystyle\\frac{1}{x - a}\\,dx = \\ln|x - a| + C\\); then combine using the log-quotient law." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\ln|x| - \\ln|x + 1| \\right] = \\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 1} = \\displaystyle\\frac{(x + 1) - x}{x(x + 1)} = \\displaystyle\\frac{1}{x(x + 1)}", explanation: "Recovers the integrand exactly." } ], finalAnswer: "\\(\\ln\\left|\\displaystyle\\frac{x}{x + 1}\\right| + C\\)." } },
  { id: "y2in7-003", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 03", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x^2 - 4}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 4 = (x - 2)(x + 2)", explanation: "Difference of squares. Two distinct linear factors, so the decomposition has form \\(\\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x + 2}\\)." }, { stepNumber: 2, description: "Set up the decomposition equation.", workingLatex: "\\displaystyle\\frac{1}{(x - 2)(x + 2)} = \\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x + 2} \\;\\Rightarrow\\; 1 = A(x + 2) + B(x - 2)", explanation: "Multiply by \\((x - 2)(x + 2)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 2:\\;\\; 1 = 4A \\Rightarrow A = \\displaystyle\\frac{1}{4}; \\quad x = -2:\\;\\; 1 = -4B \\Rightarrow B = -\\displaystyle\\frac{1}{4}", explanation: "Substitute roots of each linear factor in turn." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{1}{x^2 - 4} = \\displaystyle\\frac{1/4}{x - 2} - \\displaystyle\\frac{1/4}{x + 2}", explanation: "Each piece is a standard \\(\\displaystyle\\frac{k}{x - a}\\) form." }, { stepNumber: 5, description: "Integrate and combine logs.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{1/4}{x - 2} - \\displaystyle\\frac{1/4}{x + 2} \\right) dx = \\displaystyle\\frac{1}{4}\\ln|x - 2| - \\displaystyle\\frac{1}{4}\\ln|x + 2| + C = \\displaystyle\\frac{1}{4}\\ln\\left|\\displaystyle\\frac{x - 2}{x + 2}\\right| + C", explanation: "Standard log integrals; the log-quotient law combines them." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\displaystyle\\frac{1}{4}\\ln|x - 2| - \\displaystyle\\frac{1}{4}\\ln|x + 2| \\right] = \\displaystyle\\frac{1/4}{x - 2} - \\displaystyle\\frac{1/4}{x + 2} = \\displaystyle\\frac{(1/4)(x + 2) - (1/4)(x - 2)}{x^2 - 4} = \\displaystyle\\frac{1}{x^2 - 4}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{4}\\ln\\left|\\displaystyle\\frac{x - 2}{x + 2}\\right| + C\\)." } },
  { id: "y2in7-004", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 04", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3}{\\left(x - 1\\right)\\left(x + 2\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Denominator is already factored — set up the decomposition.", workingLatex: "\\displaystyle\\frac{3}{(x - 1)(x + 2)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Two distinct linear factors give a standard two-term decomposition." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "3 = A(x + 2) + B(x - 1)", explanation: "Multiply both sides by \\((x - 1)(x + 2)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 1:\\;\\; 3 = 3A \\Rightarrow A = 1; \\quad x = -2:\\;\\; 3 = -3B \\Rightarrow B = -1", explanation: "Substitute the roots in turn." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{3}{(x - 1)(x + 2)} = \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 2}", explanation: "Substitute the values back in." }, { stepNumber: 5, description: "Integrate and combine logs.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 2} \\right) dx = \\ln|x - 1| - \\ln|x + 2| + C = \\ln\\left|\\displaystyle\\frac{x - 1}{x + 2}\\right| + C", explanation: "Each piece integrates to a logarithm; quotient rule for logs tidies the answer." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\ln|x - 1| - \\ln|x + 2| \\right] = \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 2} = \\displaystyle\\frac{(x + 2) - (x - 1)}{(x - 1)(x + 2)} = \\displaystyle\\frac{3}{(x - 1)(x + 2)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln\\left|\\displaystyle\\frac{x - 1}{x + 2}\\right| + C\\)." } },
  { id: "y2in7-005", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 05", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x + 5}{\\left(x + 1\\right)\\left(x + 3\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{x + 5}{(x + 1)(x + 3)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 3}", explanation: "Distinct linear factors, numerator degree (\\(1\\)) is less than denominator degree (\\(2\\)) — already proper, so no division required." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "x + 5 = A(x + 3) + B(x + 1)", explanation: "Multiply by \\((x + 1)(x + 3)\\). The identity must hold for all \\(x\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = -1:\\;\\; 4 = 2A \\Rightarrow A = 2; \\quad x = -3:\\;\\; 2 = -2B \\Rightarrow B = -1", explanation: "Substitute the roots of each linear factor." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{x + 5}{(x + 1)(x + 3)} = \\displaystyle\\frac{2}{x + 1} - \\displaystyle\\frac{1}{x + 3}", explanation: "Substitute \\(A = 2\\), \\(B = -1\\)." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{2}{x + 1} - \\displaystyle\\frac{1}{x + 3} \\right) dx = 2\\ln|x + 1| - \\ln|x + 3| + C", explanation: "Standard log integrals; constants pull through." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 2\\ln|x + 1| - \\ln|x + 3| \\right] = \\displaystyle\\frac{2}{x + 1} - \\displaystyle\\frac{1}{x + 3} = \\displaystyle\\frac{2(x + 3) - (x + 1)}{(x + 1)(x + 3)} = \\displaystyle\\frac{x + 5}{(x + 1)(x + 3)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(2\\ln|x + 1| - \\ln|x + 3| + C\\)." } },
  { id: "y2in7-006", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 06", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2x + 3}{x^2 + x}\\,dx \\) (factor denominator first).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + x = x(x + 1)", explanation: "Take out the common factor \\(x\\). Two distinct linear factors, so a standard two-term decomposition." }, { stepNumber: 2, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{2x + 3}{x(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} \\;\\Rightarrow\\; 2x + 3 = A(x + 1) + Bx", explanation: "Multiply both sides by \\(x(x + 1)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\).", workingLatex: "x = 0:\\;\\; 3 = A; \\quad x = -1:\\;\\; 1 = -B \\Rightarrow B = -1", explanation: "Cover-up at each root." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{2x + 3}{x(x + 1)} = \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{1}{x + 1}", explanation: "Substitute the constants." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{1}{x + 1} \\right) dx = 3\\ln|x| - \\ln|x + 1| + C", explanation: "Standard log integrals." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 3\\ln|x| - \\ln|x + 1| \\right] = \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{1}{x + 1} = \\displaystyle\\frac{3(x + 1) - x}{x(x + 1)} = \\displaystyle\\frac{2x + 3}{x^2 + x}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(3\\ln|x| - \\ln|x + 1| + C\\)." } },
  { id: "y2in7-007", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 07", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{5}{\\left(2x + 1\\right)\\left(x - 2\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{5}{(2x + 1)(x - 2)} = \\displaystyle\\frac{A}{2x + 1} + \\displaystyle\\frac{B}{x - 2}", explanation: "Two distinct linear factors. One factor has a non-unit leading coefficient, which only affects the integration step." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "5 = A(x - 2) + B(2x + 1)", explanation: "Multiply through by \\((2x + 1)(x - 2)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 2:\\;\\; 5 = 5B \\Rightarrow B = 1; \\quad x = -\\displaystyle\\frac{1}{2}:\\;\\; 5 = -\\displaystyle\\frac{5}{2}A \\Rightarrow A = -2", explanation: "Substitute the roots of each linear factor (the root of \\(2x + 1\\) is \\(-1/2\\))." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{5}{(2x + 1)(x - 2)} = -\\displaystyle\\frac{2}{2x + 1} + \\displaystyle\\frac{1}{x - 2}", explanation: "Substitute \\(A = -2\\), \\(B = 1\\)." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( -\\displaystyle\\frac{2}{2x + 1} + \\displaystyle\\frac{1}{x - 2} \\right) dx = -\\ln|2x + 1| + \\ln|x - 2| + C", explanation: "For \\(\\displaystyle\\int \\displaystyle\\frac{1}{2x + 1}\\,dx = \\displaystyle\\frac{1}{2}\\ln|2x + 1|\\) (chain factor of \\(2\\)); combined with the \\(-2\\) coefficient this gives \\(-\\ln|2x + 1|\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -\\ln|2x + 1| + \\ln|x - 2| \\right] = -\\displaystyle\\frac{2}{2x + 1} + \\displaystyle\\frac{1}{x - 2} = \\displaystyle\\frac{-2(x - 2) + (2x + 1)}{(2x + 1)(x - 2)} = \\displaystyle\\frac{5}{(2x + 1)(x - 2)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|x - 2| - \\ln|2x + 1| + C\\)." } },
  { id: "y2in7-008", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 08", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{7}{2x^2 - x - 3}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "2x^2 - x - 3 = (2x - 3)(x + 1)", explanation: "Look for factors of \\(2 \\cdot (-3) = -6\\) that sum to \\(-1\\): \\(-3\\) and \\(2\\). Split and factor by grouping: \\(2x^2 - 3x + 2x - 3 = x(2x - 3) + (2x - 3) = (2x - 3)(x + 1)\\)." }, { stepNumber: 2, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{7}{(2x - 3)(x + 1)} = \\displaystyle\\frac{A}{2x - 3} + \\displaystyle\\frac{B}{x + 1} \\;\\Rightarrow\\; 7 = A(x + 1) + B(2x - 3)", explanation: "Multiply by \\((2x - 3)(x + 1)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = -1:\\;\\; 7 = -5B \\Rightarrow B = -\\displaystyle\\frac{7}{5}; \\quad x = \\displaystyle\\frac{3}{2}:\\;\\; 7 = \\displaystyle\\frac{5}{2}A \\Rightarrow A = \\displaystyle\\frac{14}{5}", explanation: "Substitute the root of each linear factor (root of \\(2x - 3\\) is \\(3/2\\))." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{7}{2x^2 - x - 3} = \\displaystyle\\frac{14/5}{2x - 3} - \\displaystyle\\frac{7/5}{x + 1}", explanation: "Substitute the constants back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{14/5}{2x - 3} - \\displaystyle\\frac{7/5}{x + 1} \\right) dx = \\displaystyle\\frac{14}{5} \\cdot \\displaystyle\\frac{1}{2}\\ln|2x - 3| - \\displaystyle\\frac{7}{5}\\ln|x + 1| + C = \\displaystyle\\frac{7}{5}\\ln|2x - 3| - \\displaystyle\\frac{7}{5}\\ln|x + 1| + C", explanation: "The factor of \\(\\displaystyle\\frac{1}{2}\\) on the first integral is the chain adjustment for the inner derivative \\(2\\). Then combine the coefficients." }, { stepNumber: 6, description: "Combine logs.", workingLatex: "\\displaystyle\\frac{7}{5}\\ln|2x - 3| - \\displaystyle\\frac{7}{5}\\ln|x + 1| = \\displaystyle\\frac{7}{5}\\ln\\left|\\displaystyle\\frac{2x - 3}{x + 1}\\right|", explanation: "Factor out \\(7/5\\) and apply the log-quotient law." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\displaystyle\\frac{7}{5}\\ln|2x - 3| - \\displaystyle\\frac{7}{5}\\ln|x + 1| \\right] = \\displaystyle\\frac{14/5}{2x - 3} - \\displaystyle\\frac{7/5}{x + 1} = \\displaystyle\\frac{(14/5)(x + 1) - (7/5)(2x - 3)}{(2x - 3)(x + 1)} = \\displaystyle\\frac{7}{2x^2 - x - 3}", explanation: "Recovers the integrand exactly." } ], finalAnswer: "\\(\\displaystyle\\frac{7}{5}\\ln\\left|\\displaystyle\\frac{2x - 3}{x + 1}\\right| + C\\)." } },
  { id: "y2in7-009", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 09", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3x}{\\left(x + 2\\right)\\left(x + 5\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{3x}{(x + 2)(x + 5)} = \\displaystyle\\frac{A}{x + 2} + \\displaystyle\\frac{B}{x + 5}", explanation: "Two distinct linear factors and numerator degree less than denominator degree." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "3x = A(x + 5) + B(x + 2)", explanation: "Multiply through by \\((x + 2)(x + 5)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = -2:\\;\\; -6 = 3A \\Rightarrow A = -2; \\quad x = -5:\\;\\; -15 = -3B \\Rightarrow B = 5", explanation: "Substitute the roots in turn." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{3x}{(x + 2)(x + 5)} = -\\displaystyle\\frac{2}{x + 2} + \\displaystyle\\frac{5}{x + 5}", explanation: "Substitute the constants." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( -\\displaystyle\\frac{2}{x + 2} + \\displaystyle\\frac{5}{x + 5} \\right) dx = -2\\ln|x + 2| + 5\\ln|x + 5| + C", explanation: "Two standard log integrals." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -2\\ln|x + 2| + 5\\ln|x + 5| \\right] = -\\displaystyle\\frac{2}{x + 2} + \\displaystyle\\frac{5}{x + 5} = \\displaystyle\\frac{-2(x + 5) + 5(x + 2)}{(x + 2)(x + 5)} = \\displaystyle\\frac{3x}{(x + 2)(x + 5)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-2\\ln|x + 2| + 5\\ln|x + 5| + C\\)." } },
  { id: "y2in7-010", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 10", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x}{\\left(x - 1\\right)\\left(x + 2\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition.", workingLatex: "\\displaystyle\\frac{x}{(x - 1)(x + 2)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Distinct linear factors; numerator degree is less than denominator degree." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "x = A(x + 2) + B(x - 1)", explanation: "Multiply both sides by \\((x - 1)(x + 2)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\) and \\(B\\) by cover-up.", workingLatex: "x = 1:\\;\\; 1 = 3A \\Rightarrow A = \\displaystyle\\frac{1}{3}; \\quad x = -2:\\;\\; -2 = -3B \\Rightarrow B = \\displaystyle\\frac{2}{3}", explanation: "Substitute the roots of each factor." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{x}{(x - 1)(x + 2)} = \\displaystyle\\frac{1/3}{x - 1} + \\displaystyle\\frac{2/3}{x + 2}", explanation: "Substitute the constants." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{1/3}{x - 1} + \\displaystyle\\frac{2/3}{x + 2} \\right) dx = \\displaystyle\\frac{1}{3}\\ln|x - 1| + \\displaystyle\\frac{2}{3}\\ln|x + 2| + C", explanation: "Two log integrals with fractional coefficients." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\displaystyle\\frac{1}{3}\\ln|x - 1| + \\displaystyle\\frac{2}{3}\\ln|x + 2| \\right] = \\displaystyle\\frac{1/3}{x - 1} + \\displaystyle\\frac{2/3}{x + 2} = \\displaystyle\\frac{(1/3)(x + 2) + (2/3)(x - 1)}{(x - 1)(x + 2)} = \\displaystyle\\frac{x}{(x - 1)(x + 2)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{3}\\ln|x - 1| + \\displaystyle\\frac{2}{3}\\ln|x + 2| + C\\)." } },
  // ── Three-factor ────
  { id: "y2in7-011", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 11", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{6}{x(x - 1)\\left(x + 1\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Denominator is already three distinct linear factors.", workingLatex: "x(x - 1)(x + 1) \\;\\;\\text{— three distinct linear factors}", explanation: "Three linear factors give a three-term decomposition of the form \\(\\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{x + 1}\\)." }, { stepNumber: 2, description: "Set up the decomposition equation.", workingLatex: "\\displaystyle\\frac{6}{x(x - 1)(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{x + 1} \\;\\Rightarrow\\; 6 = A(x - 1)(x + 1) + Bx(x + 1) + Cx(x - 1)", explanation: "Multiply by \\(x(x - 1)(x + 1)\\) to clear denominators." }, { stepNumber: 3, description: "Solve for \\(A\\), \\(B\\), \\(C\\) by cover-up.", workingLatex: "x = 0:\\;\\; 6 = -A \\Rightarrow A = -6; \\quad x = 1:\\;\\; 6 = 2B \\Rightarrow B = 3; \\quad x = -1:\\;\\; 6 = 2C \\Rightarrow C = 3", explanation: "Substitute each root in turn; each substitution kills two of the three unknown terms." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{6}{x(x - 1)(x + 1)} = -\\displaystyle\\frac{6}{x} + \\displaystyle\\frac{3}{x - 1} + \\displaystyle\\frac{3}{x + 1}", explanation: "Substitute back into the template." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( -\\displaystyle\\frac{6}{x} + \\displaystyle\\frac{3}{x - 1} + \\displaystyle\\frac{3}{x + 1} \\right) dx = -6\\ln|x| + 3\\ln|x - 1| + 3\\ln|x + 1| + C", explanation: "Three standard log integrals." }, { stepNumber: 6, description: "Optional log combination.", workingLatex: "-6\\ln|x| + 3\\ln|x^2 - 1| = 3\\ln\\left|\\displaystyle\\frac{x^2 - 1}{x^2}\\right| \\;\\;\\text{(equivalent compact form)}", explanation: "Using \\(3\\ln|x - 1| + 3\\ln|x + 1| = 3\\ln|x^2 - 1|\\) then \\(\\ln A - \\ln B = \\ln(A/B)\\). The expanded form is also fully acceptable." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -6\\ln|x| + 3\\ln|x - 1| + 3\\ln|x + 1| \\right] = -\\displaystyle\\frac{6}{x} + \\displaystyle\\frac{3}{x - 1} + \\displaystyle\\frac{3}{x + 1} = \\displaystyle\\frac{6}{x(x - 1)(x + 1)}", explanation: "Common-denominator combination of the three terms reproduces the integrand." } ], finalAnswer: "\\(-6\\ln|x| + 3\\ln|x - 1| + 3\\ln|x + 1| + C\\)." } },
  { id: "y2in7-012", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 12", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x(x - 1)\\left(x + 1\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Three distinct linear factors already exposed.", workingLatex: "x(x - 1)(x + 1)", explanation: "Decomposition: \\(\\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{x + 1}\\)." }, { stepNumber: 2, description: "Set up the decomposition equation.", workingLatex: "\\displaystyle\\frac{1}{x(x - 1)(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{x + 1} \\;\\Rightarrow\\; 1 = A(x - 1)(x + 1) + Bx(x + 1) + Cx(x - 1)", explanation: "Multiply through by \\(x(x - 1)(x + 1)\\)." }, { stepNumber: 3, description: "Solve for \\(A\\), \\(B\\), \\(C\\) by cover-up.", workingLatex: "x = 0:\\;\\; 1 = -A \\Rightarrow A = -1; \\quad x = 1:\\;\\; 1 = 2B \\Rightarrow B = \\displaystyle\\frac{1}{2}; \\quad x = -1:\\;\\; 1 = 2C \\Rightarrow C = \\displaystyle\\frac{1}{2}", explanation: "Substitute the three roots." }, { stepNumber: 4, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{1}{x(x - 1)(x + 1)} = -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1/2}{x - 1} + \\displaystyle\\frac{1/2}{x + 1}", explanation: "Substitute the constants back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1/2}{x - 1} + \\displaystyle\\frac{1/2}{x + 1} \\right) dx = -\\ln|x| + \\displaystyle\\frac{1}{2}\\ln|x - 1| + \\displaystyle\\frac{1}{2}\\ln|x + 1| + C", explanation: "Three log integrals." }, { stepNumber: 6, description: "Optional log combination.", workingLatex: "-\\ln|x| + \\displaystyle\\frac{1}{2}\\ln|x^2 - 1| = \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{x^2 - 1}{x^2}\\right| \\;\\;\\text{(equivalent compact form)}", explanation: "Using \\(\\displaystyle\\frac{1}{2}\\ln|x - 1| + \\displaystyle\\frac{1}{2}\\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln|x^2 - 1|\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -\\ln|x| + \\displaystyle\\frac{1}{2}\\ln|x - 1| + \\displaystyle\\frac{1}{2}\\ln|x + 1| \\right] = -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1/2}{x - 1} + \\displaystyle\\frac{1/2}{x + 1} = \\displaystyle\\frac{1}{x(x - 1)(x + 1)}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(-\\ln|x| + \\displaystyle\\frac{1}{2}\\ln|x - 1| + \\displaystyle\\frac{1}{2}\\ln|x + 1| + C\\)." } },
  // ── Repeated factor ────
  { id: "y2in7-013", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 13", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{\\left(x - 1\\right)^2}\\,dx \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "No partial fractions required — already a single power.", workingLatex: "\\displaystyle\\frac{1}{(x - 1)^2} = (x - 1)^{-2}", explanation: "A single repeated linear factor with constant numerator is already in its simplest form. Rewrite as a negative power so the standard power rule applies." }, { stepNumber: 2, description: "Apply the power rule with inner function \\(x - 1\\).", workingLatex: "\\displaystyle\\int (x - 1)^{-2}\\,dx = \\displaystyle\\frac{(x - 1)^{-1}}{-1} + C = -\\displaystyle\\frac{1}{x - 1} + C", explanation: "Use \\(\\displaystyle\\int (x - a)^n\\,dx = \\displaystyle\\frac{(x - a)^{n + 1}}{n + 1} + C\\) with \\(n = -2\\). The inner derivative \\((x - 1)' = 1\\) means no chain adjustment is needed." }, { stepNumber: 3, description: "Sanity check by differentiating.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -\\displaystyle\\frac{1}{x - 1} \\right] = -(-1)(x - 1)^{-2} = \\displaystyle\\frac{1}{(x - 1)^2}", explanation: "Differentiate using the power rule: recovers the integrand." }, { stepNumber: 4, description: "State the answer.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{(x - 1)^2}\\,dx = -\\displaystyle\\frac{1}{x - 1} + C", explanation: "Final form." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{x - 1} + C\\)." } },
  { id: "y2in7-014", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 14", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2}{x(x - 1)^2}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition with a repeated factor.", workingLatex: "\\displaystyle\\frac{2}{x(x - 1)^2} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{(x - 1)^2}", explanation: "A repeated linear factor \\((x - 1)^2\\) contributes two terms: one with denominator \\(x - 1\\) and one with \\((x - 1)^2\\)." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "2 = A(x - 1)^2 + Bx(x - 1) + Cx", explanation: "Multiply by \\(x(x - 1)^2\\). Identity in \\(x\\)." }, { stepNumber: 3, description: "Solve by cover-up at the roots.", workingLatex: "x = 0:\\;\\; 2 = A; \\quad x = 1:\\;\\; 2 = C", explanation: "Cover-up handles \\(A\\) and \\(C\\) directly. To find \\(B\\), compare another coefficient or pick a third value of \\(x\\)." }, { stepNumber: 4, description: "Find \\(B\\) by comparing coefficients of \\(x^2\\).", workingLatex: "x^2:\\;\\; 0 = A + B \\;\\Rightarrow\\; B = -A = -2", explanation: "The right-hand side expanded gives \\((A + B)x^2 + (\\ldots)x + A\\). The coefficient of \\(x^2\\) on the LHS is \\(0\\), giving \\(A + B = 0\\)." }, { stepNumber: 5, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{2}{x(x - 1)^2} = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{2}{(x - 1)^2}", explanation: "Substitute \\(A = 2\\), \\(B = -2\\), \\(C = 2\\) back into the template." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{2}{(x - 1)^2} \\right) dx = 2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{2}{x - 1} + C", explanation: "Logs for the two simple linear terms; power rule on \\(2(x - 1)^{-2}\\) gives \\(-2(x - 1)^{-1}\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{2}{x - 1} \\right] = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{2}{(x - 1)^2} = \\displaystyle\\frac{2}{x(x - 1)^2}", explanation: "Combining over the common denominator \\(x(x - 1)^2\\) gives the original integrand." } ], finalAnswer: "\\(2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{2}{x - 1} + C\\)." } },
  { id: "y2in7-015", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 15", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x}{\\left(x + 1\\right)^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the numerator in terms of the inner function.", workingLatex: "x = (x + 1) - 1", explanation: "This trick saves a full decomposition: write the numerator as a multiple of the inner function plus a constant." }, { stepNumber: 2, description: "Split the fraction.", workingLatex: "\\displaystyle\\frac{x}{(x + 1)^2} = \\displaystyle\\frac{(x + 1) - 1}{(x + 1)^2} = \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{(x + 1)^2}", explanation: "Each term is now in standard form: a simple \\(1/(x + 1)\\) log and a power \\((x + 1)^{-2}\\)." }, { stepNumber: 3, description: "Confirm decomposition form (sanity).", workingLatex: "\\displaystyle\\frac{x}{(x + 1)^2} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{(x + 1)^2}, \\quad A = 1,\\, B = -1", explanation: "This is the same decomposition as a formal partial-fraction setup would yield with the repeated factor." }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{(x + 1)^2} \\right) dx = \\ln|x + 1| - \\left( -\\displaystyle\\frac{1}{x + 1} \\right) + C = \\ln|x + 1| + \\displaystyle\\frac{1}{x + 1} + C", explanation: "Log integral for the first piece; power rule \\((x + 1)^{-2} \\to -(x + 1)^{-1}\\) for the second, with the leading minus flipping the sign to \\(+\\)." }, { stepNumber: 5, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\ln|x + 1| + \\displaystyle\\frac{1}{x + 1} \\right] = \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{(x + 1)^2} = \\displaystyle\\frac{(x + 1) - 1}{(x + 1)^2} = \\displaystyle\\frac{x}{(x + 1)^2}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln|x + 1| + \\displaystyle\\frac{1}{x + 1} + C\\)." } },
  { id: "y2in7-016", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 16", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3x + 2}{x(x + 1)^2}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition with a repeated factor.", workingLatex: "\\displaystyle\\frac{3x + 2}{x(x + 1)^2} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} + \\displaystyle\\frac{C}{(x + 1)^2}", explanation: "Repeated factor \\((x + 1)^2\\) contributes two terms." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "3x + 2 = A(x + 1)^2 + Bx(x + 1) + Cx", explanation: "Multiply through by \\(x(x + 1)^2\\)." }, { stepNumber: 3, description: "Solve by cover-up at the roots.", workingLatex: "x = 0:\\;\\; 2 = A; \\quad x = -1:\\;\\; -1 = -C \\Rightarrow C = 1", explanation: "Two of the three unknowns drop out directly." }, { stepNumber: 4, description: "Find \\(B\\) by comparing coefficients of \\(x^2\\).", workingLatex: "x^2:\\;\\; 0 = A + B \\;\\Rightarrow\\; B = -2", explanation: "The LHS has no \\(x^2\\) term, so the \\(x^2\\) coefficients on the RHS must sum to zero." }, { stepNumber: 5, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{3x + 2}{x(x + 1)^2} = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x + 1} + \\displaystyle\\frac{1}{(x + 1)^2}", explanation: "Substitute \\(A = 2\\), \\(B = -2\\), \\(C = 1\\)." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x + 1} + \\displaystyle\\frac{1}{(x + 1)^2} \\right) dx = 2\\ln|x| - 2\\ln|x + 1| - \\displaystyle\\frac{1}{x + 1} + C", explanation: "Two log integrals plus a power-rule term: \\((x + 1)^{-2} \\to -(x + 1)^{-1}\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 2\\ln|x| - 2\\ln|x + 1| - \\displaystyle\\frac{1}{x + 1} \\right] = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x + 1} + \\displaystyle\\frac{1}{(x + 1)^2} = \\displaystyle\\frac{3x + 2}{x(x + 1)^2}", explanation: "Combining over \\(x(x + 1)^2\\) gives the original integrand." } ], finalAnswer: "\\(2\\ln|x| - 2\\ln|x + 1| - \\displaystyle\\frac{1}{x + 1} + C\\)." } },
  { id: "y2in7-017", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 17", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{4x - 3}{\\left(x - 1\\right)^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Rewrite the numerator in terms of the inner function.", workingLatex: "4x - 3 = 4(x - 1) + 1", explanation: "Expand: \\(4(x - 1) + 1 = 4x - 4 + 1 = 4x - 3\\). This rewrite lets us split the fraction without a formal decomposition." }, { stepNumber: 2, description: "Split the fraction.", workingLatex: "\\displaystyle\\frac{4x - 3}{(x - 1)^2} = \\displaystyle\\frac{4(x - 1)}{(x - 1)^2} + \\displaystyle\\frac{1}{(x - 1)^2} = \\displaystyle\\frac{4}{x - 1} + \\displaystyle\\frac{1}{(x - 1)^2}", explanation: "Cancel one factor of \\(x - 1\\) from the first piece. Each resulting term is now a standard integral." }, { stepNumber: 3, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( \\displaystyle\\frac{4}{x - 1} + \\displaystyle\\frac{1}{(x - 1)^2} \\right) dx = 4\\ln|x - 1| - \\displaystyle\\frac{1}{x - 1} + C", explanation: "Log integral for the first piece; power rule \\((x - 1)^{-2} \\to -(x - 1)^{-1}\\) for the second." }, { stepNumber: 4, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ 4\\ln|x - 1| - \\displaystyle\\frac{1}{x - 1} \\right] = \\displaystyle\\frac{4}{x - 1} + \\displaystyle\\frac{1}{(x - 1)^2} = \\displaystyle\\frac{4(x - 1) + 1}{(x - 1)^2} = \\displaystyle\\frac{4x - 3}{(x - 1)^2}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(4\\ln|x - 1| - \\displaystyle\\frac{1}{x - 1} + C\\)." } },
  { id: "y2in7-018", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 18", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x^2\\left(x + 1\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the decomposition with a repeated factor.", workingLatex: "\\displaystyle\\frac{1}{x^2(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x^2} + \\displaystyle\\frac{C}{x + 1}", explanation: "The repeated factor \\(x^2\\) contributes two terms (one with denominator \\(x\\), one with \\(x^2\\)), and \\(x + 1\\) gives one more." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "1 = Ax(x + 1) + B(x + 1) + Cx^2", explanation: "Multiply through by \\(x^2(x + 1)\\)." }, { stepNumber: 3, description: "Solve by cover-up at the roots.", workingLatex: "x = 0:\\;\\; 1 = B; \\quad x = -1:\\;\\; 1 = C", explanation: "Two unknowns fall out directly." }, { stepNumber: 4, description: "Find \\(A\\) by comparing coefficients of \\(x^2\\).", workingLatex: "x^2:\\;\\; 0 = A + C \\;\\Rightarrow\\; A = -1", explanation: "The LHS has no \\(x^2\\) term; on the RHS the coefficient of \\(x^2\\) is \\(A + C\\)." }, { stepNumber: 5, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{1}{x^2(x + 1)} = -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} + \\displaystyle\\frac{1}{x + 1}", explanation: "Substitute \\(A = -1\\), \\(B = 1\\), \\(C = 1\\)." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} + \\displaystyle\\frac{1}{x + 1} \\right) dx = -\\ln|x| - \\displaystyle\\frac{1}{x} + \\ln|x + 1| + C", explanation: "Log integrals for the simple \\(1/x\\) and \\(1/(x + 1)\\) terms; power rule \\(x^{-2} \\to -x^{-1}\\) for the repeated piece." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ -\\ln|x| - \\displaystyle\\frac{1}{x} + \\ln|x + 1| \\right] = -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} + \\displaystyle\\frac{1}{x + 1} = \\displaystyle\\frac{1}{x^2(x + 1)}", explanation: "Combining over \\(x^2(x + 1)\\) gives the original integrand." } ], finalAnswer: "\\(-\\ln|x| - \\displaystyle\\frac{1}{x} + \\ln|x + 1| + C\\)." } },
  // ── Improper rational ────
  { id: "y2in7-019", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 19", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2}{x^2 - 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Check degrees and divide.", workingLatex: "\\deg(x^2) = \\deg(x^2 - 1) \\;\\Rightarrow\\; \\text{improper; polynomial division required}", explanation: "When the numerator's degree is at least the denominator's, divide first to extract a polynomial part plus a proper remainder." }, { stepNumber: 2, description: "Perform the polynomial division.", workingLatex: "\\displaystyle\\frac{x^2}{x^2 - 1} = \\displaystyle\\frac{(x^2 - 1) + 1}{x^2 - 1} = 1 + \\displaystyle\\frac{1}{x^2 - 1}", explanation: "Add and subtract \\(1\\) in the numerator: \\(x^2 = (x^2 - 1) + 1\\). The proper remainder is \\(1/(x^2 - 1)\\)." }, { stepNumber: 3, description: "Decompose the proper part.", workingLatex: "\\displaystyle\\frac{1}{x^2 - 1} = \\displaystyle\\frac{1}{(x - 1)(x + 1)} = \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1}", explanation: "Difference of squares, then cover-up: at \\(x = 1\\), \\(1 = 2A \\Rightarrow A = 1/2\\); at \\(x = -1\\), \\(1 = -2B \\Rightarrow B = -1/2\\)." }, { stepNumber: 4, description: "Assemble the full integrand.", workingLatex: "\\displaystyle\\frac{x^2}{x^2 - 1} = 1 + \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1}", explanation: "Polynomial part plus the decomposition." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( 1 + \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1} \\right) dx = x + \\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{1}{2}\\ln|x + 1| + C", explanation: "Constant integrates to \\(x\\); the two log terms come from the standard reciprocal-linear integrals." }, { stepNumber: 6, description: "Combine logs.", workingLatex: "\\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{1}{2}\\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Log-quotient law." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ x + \\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{1}{2}\\ln|x + 1| \\right] = 1 + \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1} = 1 + \\displaystyle\\frac{1}{x^2 - 1} = \\displaystyle\\frac{x^2}{x^2 - 1}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(x + \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| + C\\)." } },
  { id: "y2in7-020", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 20", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2 + 1}{x^2 - 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Check degrees and divide.", workingLatex: "\\deg(x^2 + 1) = \\deg(x^2 - 1) \\;\\Rightarrow\\; \\text{improper}", explanation: "Equal degrees mean the rational expression is improper. Divide first." }, { stepNumber: 2, description: "Perform polynomial division.", workingLatex: "\\displaystyle\\frac{x^2 + 1}{x^2 - 1} = \\displaystyle\\frac{(x^2 - 1) + 2}{x^2 - 1} = 1 + \\displaystyle\\frac{2}{x^2 - 1}", explanation: "Write \\(x^2 + 1 = (x^2 - 1) + 2\\) to separate the polynomial part." }, { stepNumber: 3, description: "Decompose the proper remainder.", workingLatex: "\\displaystyle\\frac{2}{x^2 - 1} = \\displaystyle\\frac{2}{(x - 1)(x + 1)} = \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 1}", explanation: "Cover-up: \\(2 = A(x + 1) + B(x - 1)\\); at \\(x = 1\\), \\(A = 1\\); at \\(x = -1\\), \\(B = -1\\)." }, { stepNumber: 4, description: "Assemble the full integrand.", workingLatex: "\\displaystyle\\frac{x^2 + 1}{x^2 - 1} = 1 + \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 1}", explanation: "Polynomial part plus the decomposed proper fraction." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( 1 + \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 1} \\right) dx = x + \\ln|x - 1| - \\ln|x + 1| + C", explanation: "Constant integrates to \\(x\\); the log integrals follow standard rules." }, { stepNumber: 6, description: "Combine logs.", workingLatex: "\\ln|x - 1| - \\ln|x + 1| = \\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Log-quotient law." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ x + \\ln|x - 1| - \\ln|x + 1| \\right] = 1 + \\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 1} = 1 + \\displaystyle\\frac{2}{x^2 - 1} = \\displaystyle\\frac{x^2 + 1}{x^2 - 1}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(x + \\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| + C\\)." } },
  { id: "y2in7-021", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 21", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^3}{x^2 - 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Check degrees and divide.", workingLatex: "\\deg(x^3) > \\deg(x^2 - 1) \\;\\Rightarrow\\; \\text{improper, polynomial division required}", explanation: "Numerator degree exceeds denominator degree, so divide first." }, { stepNumber: 2, description: "Perform polynomial division.", workingLatex: "x^3 = x(x^2 - 1) + x \\;\\Rightarrow\\; \\displaystyle\\frac{x^3}{x^2 - 1} = x + \\displaystyle\\frac{x}{x^2 - 1}", explanation: "Multiply out: \\(x(x^2 - 1) + x = x^3 - x + x = x^3\\). The remainder \\(x/(x^2 - 1)\\) is proper (degree \\(1 < 2\\))." }, { stepNumber: 3, description: "Recognise the proper part as a reverse-chain logarithm.", workingLatex: "\\displaystyle\\frac{x}{x^2 - 1} = \\displaystyle\\frac{1}{2} \\cdot \\displaystyle\\frac{2x}{x^2 - 1}", explanation: "The numerator \\(2x\\) is exactly the derivative of \\(x^2 - 1\\). The reverse-chain pattern \\(\\displaystyle\\int \\displaystyle\\frac{f'}{f}\\,dx = \\ln|f|\\) applies — no partial fractions needed for this remainder." }, { stepNumber: 4, description: "Assemble the full integrand.", workingLatex: "\\displaystyle\\frac{x^3}{x^2 - 1} = x + \\displaystyle\\frac{1}{2} \\cdot \\displaystyle\\frac{2x}{x^2 - 1}", explanation: "Polynomial part plus the reverse-chain-ready term." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\left( x + \\displaystyle\\frac{1}{2} \\cdot \\displaystyle\\frac{2x}{x^2 - 1} \\right) dx = \\displaystyle\\frac{x^2}{2} + \\displaystyle\\frac{1}{2}\\ln|x^2 - 1| + C", explanation: "Power rule on \\(x\\); reverse-chain log on the second term." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\left[ \\displaystyle\\frac{x^2}{2} + \\displaystyle\\frac{1}{2}\\ln|x^2 - 1| \\right] = x + \\displaystyle\\frac{1}{2} \\cdot \\displaystyle\\frac{2x}{x^2 - 1} = x + \\displaystyle\\frac{x}{x^2 - 1} = \\displaystyle\\frac{x(x^2 - 1) + x}{x^2 - 1} = \\displaystyle\\frac{x^3}{x^2 - 1}", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{x^2}{2} + \\displaystyle\\frac{1}{2}\\ln|x^2 - 1| + C\\)." } },
  // ── Definite integrals ────
  { id: "y2in7-022", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 22", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_2^3 \\displaystyle\\frac{1}{x^2 - 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor and decompose.", workingLatex: "\\displaystyle\\frac{1}{x^2 - 1} = \\displaystyle\\frac{1}{(x - 1)(x + 1)} = \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1}", explanation: "Difference of squares; cover-up gives \\(A = 1/2\\), \\(B = -1/2\\) (as in y2in7-003 scaled by \\(2\\) on the numerator, then halved)." }, { stepNumber: 2, description: "Write the antiderivative.", workingLatex: "F(x) = \\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{1}{2}\\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Integrate each piece; combine using the log-quotient law for a compact closed form." }, { stepNumber: 3, description: "Apply the fundamental theorem.", workingLatex: "\\displaystyle\\int_2^3 \\displaystyle\\frac{1}{x^2 - 1}\\,dx = \\left[ \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| \\right]_2^3", explanation: "Evaluate the antiderivative at the upper limit minus its value at the lower limit." }, { stepNumber: 4, description: "Substitute the limits.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{2}{4}\\right| - \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{1}{3}\\right| = \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{1}{2} - \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{1}{3}", explanation: "At \\(x = 3\\): \\((x - 1)/(x + 1) = 2/4 = 1/2\\). At \\(x = 2\\): \\(1/3\\). Both positive, so the absolute values drop." }, { stepNumber: 5, description: "Simplify using log laws.", workingLatex: "\\displaystyle\\frac{1}{2}\\left( \\ln\\displaystyle\\frac{1}{2} - \\ln\\displaystyle\\frac{1}{3} \\right) = \\displaystyle\\frac{1}{2}\\ln\\left( \\displaystyle\\frac{1/2}{1/3} \\right) = \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{3}{2}", explanation: "Log-quotient law: \\(\\ln a - \\ln b = \\ln(a/b)\\). Then \\((1/2) \\div (1/3) = 3/2\\)." }, { stepNumber: 6, description: "State the final value.", workingLatex: "\\displaystyle\\int_2^3 \\displaystyle\\frac{1}{x^2 - 1}\\,dx = \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{3}{2}", explanation: "A positive value, as expected — the integrand is positive on \\([2, 3]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{3}{2}\\)." } },
  { id: "y2in7-023", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 23", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_1^2 \\displaystyle\\frac{1}{x(x + 1)}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Decompose the integrand.", workingLatex: "\\displaystyle\\frac{1}{x(x + 1)} = \\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 1}", explanation: "Distinct linear factors. Cover-up: at \\(x = 0\\), \\(A = 1\\); at \\(x = -1\\), \\(B = -1\\)." }, { stepNumber: 2, description: "Write the antiderivative.", workingLatex: "F(x) = \\ln|x| - \\ln|x + 1| = \\ln\\left|\\displaystyle\\frac{x}{x + 1}\\right|", explanation: "Two log integrals combined via the quotient law." }, { stepNumber: 3, description: "Apply the fundamental theorem.", workingLatex: "\\displaystyle\\int_1^2 \\displaystyle\\frac{1}{x(x + 1)}\\,dx = \\left[ \\ln\\left|\\displaystyle\\frac{x}{x + 1}\\right| \\right]_1^2", explanation: "Antiderivative at upper minus lower." }, { stepNumber: 4, description: "Substitute the limits.", workingLatex: "= \\ln\\displaystyle\\frac{2}{3} - \\ln\\displaystyle\\frac{1}{2}", explanation: "At \\(x = 2\\): \\(2/3\\). At \\(x = 1\\): \\(1/2\\). Both positive on \\([1, 2]\\)." }, { stepNumber: 5, description: "Simplify using log laws.", workingLatex: "\\ln\\displaystyle\\frac{2}{3} - \\ln\\displaystyle\\frac{1}{2} = \\ln\\left( \\displaystyle\\frac{2/3}{1/2} \\right) = \\ln\\displaystyle\\frac{4}{3}", explanation: "Log-quotient law; \\((2/3) \\div (1/2) = 4/3\\)." }, { stepNumber: 6, description: "State the final value.", workingLatex: "\\displaystyle\\int_1^2 \\displaystyle\\frac{1}{x(x + 1)}\\,dx = \\ln\\displaystyle\\frac{4}{3}", explanation: "Positive, as the integrand is positive on \\([1, 2]\\)." } ], finalAnswer: "\\(\\ln\\displaystyle\\frac{4}{3}\\)." } },
  { id: "y2in7-024", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 24", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_3^5 \\displaystyle\\frac{1}{x^2 - 4}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor and decompose.", workingLatex: "\\displaystyle\\frac{1}{x^2 - 4} = \\displaystyle\\frac{1}{(x - 2)(x + 2)} = \\displaystyle\\frac{1/4}{x - 2} - \\displaystyle\\frac{1/4}{x + 2}", explanation: "Difference of squares; cover-up at \\(x = 2\\) gives \\(A = 1/4\\); at \\(x = -2\\), \\(B = -1/4\\)." }, { stepNumber: 2, description: "Write the antiderivative.", workingLatex: "F(x) = \\displaystyle\\frac{1}{4}\\ln|x - 2| - \\displaystyle\\frac{1}{4}\\ln|x + 2| = \\displaystyle\\frac{1}{4}\\ln\\left|\\displaystyle\\frac{x - 2}{x + 2}\\right|", explanation: "Two log integrals combined via the quotient law." }, { stepNumber: 3, description: "Apply the fundamental theorem.", workingLatex: "\\displaystyle\\int_3^5 \\displaystyle\\frac{1}{x^2 - 4}\\,dx = \\left[ \\displaystyle\\frac{1}{4}\\ln\\left|\\displaystyle\\frac{x - 2}{x + 2}\\right| \\right]_3^5", explanation: "Antiderivative evaluated from \\(3\\) to \\(5\\)." }, { stepNumber: 4, description: "Substitute the limits.", workingLatex: "= \\displaystyle\\frac{1}{4}\\ln\\displaystyle\\frac{3}{7} - \\displaystyle\\frac{1}{4}\\ln\\displaystyle\\frac{1}{5}", explanation: "At \\(x = 5\\): \\((x - 2)/(x + 2) = 3/7\\). At \\(x = 3\\): \\(1/5\\). Both positive on \\([3, 5]\\)." }, { stepNumber: 5, description: "Simplify using log laws.", workingLatex: "\\displaystyle\\frac{1}{4}\\left( \\ln\\displaystyle\\frac{3}{7} - \\ln\\displaystyle\\frac{1}{5} \\right) = \\displaystyle\\frac{1}{4}\\ln\\left( \\displaystyle\\frac{3/7}{1/5} \\right) = \\displaystyle\\frac{1}{4}\\ln\\displaystyle\\frac{15}{7}", explanation: "Log-quotient law; \\((3/7) \\div (1/5) = 15/7\\)." }, { stepNumber: 6, description: "State the final value.", workingLatex: "\\displaystyle\\int_3^5 \\displaystyle\\frac{1}{x^2 - 4}\\,dx = \\displaystyle\\frac{1}{4}\\ln\\displaystyle\\frac{15}{7}", explanation: "Positive, as the integrand is positive on \\([3, 5]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{4}\\ln\\displaystyle\\frac{15}{7}\\)." } },
  { id: "y2in7-025", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 25", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\displaystyle\\frac{3}{\\left(2x + 1\\right)\\left(x + 2\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Note the denominator is already factored.", workingLatex: "(2x + 1)(x + 2)", explanation: "Two distinct linear factors — the standard decomposition into \\(\\displaystyle\\frac{A}{2x + 1} + \\displaystyle\\frac{B}{x + 2}\\) applies." }, { stepNumber: 2, description: "Set up the partial-fraction form.", workingLatex: "\\displaystyle\\frac{3}{(2x + 1)(x + 2)} = \\displaystyle\\frac{A}{2x + 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Distinct linear factors get their own constant numerators." }, { stepNumber: 3, description: "Clear denominators and solve by substitution.", workingLatex: "3 = A(x + 2) + B(2x + 1)", explanation: "Multiply both sides by \\((2x + 1)(x + 2)\\). Use cover-up: at \\(x = -2\\), \\(3 = B(-3)\\Rightarrow B = -1\\); at \\(x = -\\displaystyle\\frac{1}{2}\\), \\(3 = A\\!\\left(\\displaystyle\\frac{3}{2}\\right)\\Rightarrow A = 2\\)." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{3}{(2x + 1)(x + 2)} = \\displaystyle\\frac{2}{2x + 1} - \\displaystyle\\frac{1}{x + 2}", explanation: "Substitute the constants back into the form." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{2}{2x + 1} - \\displaystyle\\frac{1}{x + 2}\\right]dx = \\ln|2x + 1| - \\ln|x + 2|", explanation: "\\(\\displaystyle\\int \\displaystyle\\frac{2}{2x + 1}\\,dx = \\ln|2x + 1|\\) since the numerator is the derivative of the denominator; \\(\\displaystyle\\int \\displaystyle\\frac{1}{x + 2}\\,dx = \\ln|x + 2|\\)." }, { stepNumber: 6, description: "Apply the limits \\(0\\) and \\(1\\).", workingLatex: "\\left[\\ln|2x + 1| - \\ln|x + 2|\\right]_0^1 = \\left(\\ln 3 - \\ln 3\\right) - \\left(\\ln 1 - \\ln 2\\right)", explanation: "Top: \\(\\ln 3 - \\ln 3 = 0\\). Bottom: \\(\\ln 1 - \\ln 2 = -\\ln 2\\). Difference: \\(0 - (-\\ln 2) = \\ln 2\\)." }, { stepNumber: 7, description: "Simplify.", workingLatex: "= \\ln 2", explanation: "The two \\(\\ln 3\\) terms cancel and only \\(\\ln 2\\) survives." } ], finalAnswer: "\\(\\ln 2\\)." } },
  { id: "y2in7-026", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 26", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^2 \\displaystyle\\frac{x + 4}{\\left(x + 1\\right)\\left(x + 3\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{x + 4}{(x + 1)(x + 3)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 3}", explanation: "Distinct linear factors — one constant numerator above each." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "x + 4 = A(x + 3) + B(x + 1)", explanation: "Multiply both sides by \\((x + 1)(x + 3)\\)." }, { stepNumber: 3, description: "Solve by cover-up.", workingLatex: "x = -1:\\;3 = 2A\\Rightarrow A = \\displaystyle\\frac{3}{2};\\quad x = -3:\\;1 = -2B\\Rightarrow B = -\\displaystyle\\frac{1}{2}", explanation: "Substitute the roots of each linear factor to isolate one constant at a time." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x + 4}{(x + 1)(x + 3)} = \\displaystyle\\frac{3/2}{x + 1} - \\displaystyle\\frac{1/2}{x + 3}", explanation: "Substitute the constants back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{3/2}{x + 1} - \\displaystyle\\frac{1/2}{x + 3}\\right]dx = \\displaystyle\\frac{3}{2}\\ln|x + 1| - \\displaystyle\\frac{1}{2}\\ln|x + 3|", explanation: "Each piece is a constant over a linear factor — standard log." }, { stepNumber: 6, description: "Apply limits 0 to 2.", workingLatex: "\\left[\\displaystyle\\frac{3}{2}\\ln|x + 1| - \\displaystyle\\frac{1}{2}\\ln|x + 3|\\right]_0^2 = \\left(\\displaystyle\\frac{3}{2}\\ln 3 - \\displaystyle\\frac{1}{2}\\ln 5\\right) - \\left(0 - \\displaystyle\\frac{1}{2}\\ln 3\\right)", explanation: "At \\(x = 2\\): \\(\\displaystyle\\frac{3}{2}\\ln 3 - \\displaystyle\\frac{1}{2}\\ln 5\\). At \\(x = 0\\): \\(\\displaystyle\\frac{3}{2}\\ln 1 - \\displaystyle\\frac{1}{2}\\ln 3 = -\\displaystyle\\frac{1}{2}\\ln 3\\)." }, { stepNumber: 7, description: "Simplify using log laws.", workingLatex: "= 2\\ln 3 - \\displaystyle\\frac{1}{2}\\ln 5 = \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{81}{5}", explanation: "Combine the two \\(\\ln 3\\) contributions: \\(\\displaystyle\\frac{3}{2} + \\displaystyle\\frac{1}{2} = 2\\). Then \\(2\\ln 3 = \\ln 9 = \\displaystyle\\frac{1}{2}\\ln 81\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{3}{2}\\ln 3 - \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{5}{3} = \\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{81}{5}\\)." } },
  // ── More ────
  { id: "y2in7-027", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 27", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2}{x^2 + 4x + 3}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + 4x + 3 = (x + 1)(x + 3)", explanation: "Two numbers multiplying to \\(3\\) and adding to \\(4\\) are \\(1\\) and \\(3\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{2}{(x + 1)(x + 3)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 3}", explanation: "Distinct linear factors take constants on top." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "2 = A(x + 3) + B(x + 1);\\;x = -1:A = 1;\\;x = -3:B = -1", explanation: "Cover-up: substitute each root to isolate one constant." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2}{(x + 1)(x + 3)} = \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{x + 3}", explanation: "Both numerators are constants over linear denominators." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{x + 3}\\right]dx = \\ln|x + 1| - \\ln|x + 3| + C", explanation: "Standard \\(\\displaystyle\\int \\displaystyle\\frac{1}{x + a}\\,dx = \\ln|x + a|\\)." }, { stepNumber: 6, description: "Combine using log laws.", workingLatex: "= \\ln\\!\\left|\\displaystyle\\frac{x + 1}{x + 3}\\right| + C", explanation: "\\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln\\!\\left|\\displaystyle\\frac{x + 1}{x + 3}\\right| = \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{x + 3} = \\displaystyle\\frac{2}{(x + 1)(x + 3)}\\;\\checkmark", explanation: "Recovers the integrand exactly." } ], finalAnswer: "\\(\\ln\\left|\\displaystyle\\frac{x + 1}{x + 3}\\right| + C\\)." } },
  { id: "y2in7-028", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 28", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x + 1}{x^2 - 5x + 6}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 5x + 6 = (x - 2)(x - 3)", explanation: "Numbers multiplying to \\(6\\) and adding to \\(-5\\): \\(-2\\) and \\(-3\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{x + 1}{(x - 2)(x - 3)} = \\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x - 3}", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "x + 1 = A(x - 3) + B(x - 2);\\;x = 2:3 = -A\\Rightarrow A = -3;\\;x = 3:4 = B", explanation: "Cover-up at each root: \\(x = 2\\) kills the \\(B\\) term, \\(x = 3\\) kills the \\(A\\) term." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x + 1}{(x - 2)(x - 3)} = -\\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{4}{x - 3}", explanation: "Substitute the constants back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[-\\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{4}{x - 3}\\right]dx = -3\\ln|x - 2| + 4\\ln|x - 3| + C", explanation: "Each piece is a constant over linear — \\(\\ln\\) antiderivative." }, { stepNumber: 6, description: "Tidy.", workingLatex: "= 4\\ln|x - 3| - 3\\ln|x - 2| + C", explanation: "Re-order for clarity." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[4\\ln|x - 3| - 3\\ln|x - 2|\\right] = \\displaystyle\\frac{4}{x - 3} - \\displaystyle\\frac{3}{x - 2} = \\displaystyle\\frac{x + 1}{(x - 2)(x - 3)}\\;\\checkmark", explanation: "Common denominator gives \\(\\displaystyle\\frac{4(x - 2) - 3(x - 3)}{(x - 2)(x - 3)} = \\displaystyle\\frac{x + 1}{(x - 2)(x - 3)}\\)." } ], finalAnswer: "\\(4\\ln|x - 3| - 3\\ln|x - 2| + C\\)." } },
  { id: "y2in7-029", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 29", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x^2 + 5x + 6}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + 5x + 6 = (x + 2)(x + 3)", explanation: "Numbers multiplying to \\(6\\) and adding to \\(5\\): \\(2\\) and \\(3\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{1}{(x + 2)(x + 3)} = \\displaystyle\\frac{A}{x + 2} + \\displaystyle\\frac{B}{x + 3}", explanation: "Distinct linear factors." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "1 = A(x + 3) + B(x + 2);\\;x = -2:A = 1;\\;x = -3:B = -1", explanation: "Cover-up substitution at each root." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{(x + 2)(x + 3)} = \\displaystyle\\frac{1}{x + 2} - \\displaystyle\\frac{1}{x + 3}", explanation: "Plug constants back in." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1}{x + 2} - \\displaystyle\\frac{1}{x + 3}\\right]dx = \\ln|x + 2| - \\ln|x + 3| + C", explanation: "Each piece is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 6, description: "Combine logs.", workingLatex: "= \\ln\\!\\left|\\displaystyle\\frac{x + 2}{x + 3}\\right| + C", explanation: "Apply \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln\\!\\left|\\displaystyle\\frac{x + 2}{x + 3}\\right| = \\displaystyle\\frac{1}{x + 2} - \\displaystyle\\frac{1}{x + 3} = \\displaystyle\\frac{1}{(x + 2)(x + 3)}\\;\\checkmark", explanation: "Combining the two terms gives the original integrand." } ], finalAnswer: "\\(\\ln\\left|\\displaystyle\\frac{x + 2}{x + 3}\\right| + C\\)." } },
  { id: "y2in7-030", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 30", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3x - 2}{x^2 - x - 6}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - x - 6 = (x - 3)(x + 2)", explanation: "Numbers multiplying to \\(-6\\) and adding to \\(-1\\): \\(-3\\) and \\(2\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{3x - 2}{(x - 3)(x + 2)} = \\displaystyle\\frac{A}{x - 3} + \\displaystyle\\frac{B}{x + 2}", explanation: "Distinct linear factors." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "3x - 2 = A(x + 2) + B(x - 3);\\;x = 3:7 = 5A\\Rightarrow A = \\displaystyle\\frac{7}{5};\\;x = -2:-8 = -5B\\Rightarrow B = \\displaystyle\\frac{8}{5}", explanation: "Substitute each root in turn." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{3x - 2}{(x - 3)(x + 2)} = \\displaystyle\\frac{7/5}{x - 3} + \\displaystyle\\frac{8/5}{x + 2}", explanation: "Plug constants back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{7/5}{x - 3} + \\displaystyle\\frac{8/5}{x + 2}\\right]dx = \\displaystyle\\frac{7}{5}\\ln|x - 3| + \\displaystyle\\frac{8}{5}\\ln|x + 2| + C", explanation: "Constant over linear gives \\(\\ln\\) of the linear factor." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{7}{5}\\ln|x - 3| + \\displaystyle\\frac{8}{5}\\ln|x + 2|\\right] = \\displaystyle\\frac{7/5}{x - 3} + \\displaystyle\\frac{8/5}{x + 2} = \\displaystyle\\frac{3x - 2}{(x - 3)(x + 2)}\\;\\checkmark", explanation: "Common denominator: \\(\\displaystyle\\frac{7}{5}(x + 2) + \\displaystyle\\frac{8}{5}(x - 3) = \\displaystyle\\frac{15x - 10}{5} = 3x - 2\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{7}{5}\\ln|x - 3| + \\displaystyle\\frac{8}{5}\\ln|x + 2| + C\\)." } },
  { id: "y2in7-031", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 31", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{6}{\\left(2x - 1\\right)\\left(2x + 1\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Denominator already factored.", workingLatex: "(2x - 1)(2x + 1)", explanation: "Two distinct linear factors." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{6}{(2x - 1)(2x + 1)} = \\displaystyle\\frac{A}{2x - 1} + \\displaystyle\\frac{B}{2x + 1}", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "6 = A(2x + 1) + B(2x - 1);\\;x = \\displaystyle\\frac{1}{2}:6 = 2A\\Rightarrow A = 3;\\;x = -\\displaystyle\\frac{1}{2}:6 = -2B\\Rightarrow B = -3", explanation: "Substitute the roots of each linear factor." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{6}{(2x - 1)(2x + 1)} = \\displaystyle\\frac{3}{2x - 1} - \\displaystyle\\frac{3}{2x + 1}", explanation: "Plug constants back in." }, { stepNumber: 5, description: "Integrate each piece using the \\(2x \\pm 1\\) derivative.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{3}{2x - 1}\\,dx = \\displaystyle\\frac{3}{2}\\ln|2x - 1|;\\quad \\displaystyle\\int \\displaystyle\\frac{3}{2x + 1}\\,dx = \\displaystyle\\frac{3}{2}\\ln|2x + 1|", explanation: "\\(\\displaystyle\\int \\displaystyle\\frac{1}{2x + a}\\,dx = \\displaystyle\\frac{1}{2}\\ln|2x + a|\\) — divide by the coefficient of \\(x\\)." }, { stepNumber: 6, description: "Combine logs.", workingLatex: "= \\displaystyle\\frac{3}{2}\\ln|2x - 1| - \\displaystyle\\frac{3}{2}\\ln|2x + 1| + C = \\displaystyle\\frac{3}{2}\\ln\\!\\left|\\displaystyle\\frac{2x - 1}{2x + 1}\\right| + C", explanation: "\\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{3}{2}\\ln\\!\\left|\\displaystyle\\frac{2x - 1}{2x + 1}\\right|\\right] = \\displaystyle\\frac{3}{2}\\!\\left(\\displaystyle\\frac{2}{2x - 1} - \\displaystyle\\frac{2}{2x + 1}\\right) = \\displaystyle\\frac{6}{(2x - 1)(2x + 1)}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{3}{2}\\ln\\left|\\displaystyle\\frac{2x - 1}{2x + 1}\\right| + C\\)." } },
  { id: "y2in7-032", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 32", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{x(x + 1)\\left(x + 2\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Three distinct linear factors.", workingLatex: "x,\\;(x + 1),\\;(x + 2)", explanation: "Each gets a constant numerator." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{1}{x(x + 1)(x + 2)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} + \\displaystyle\\frac{C}{x + 2}", explanation: "Standard form for three distinct linear factors." }, { stepNumber: 3, description: "Combine over common denominator.", workingLatex: "1 = A(x + 1)(x + 2) + Bx(x + 2) + Cx(x + 1)", explanation: "Multiply both sides by \\(x(x + 1)(x + 2)\\)." }, { stepNumber: 4, description: "Cover-up at each root.", workingLatex: "x = 0:1 = 2A\\Rightarrow A = \\displaystyle\\frac{1}{2};\\;x = -1:1 = -B\\Rightarrow B = -1;\\;x = -2:1 = 2C\\Rightarrow C = \\displaystyle\\frac{1}{2}", explanation: "Each substitution kills two of the three terms, isolating one constant." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{x(x + 1)(x + 2)} = \\displaystyle\\frac{1/2}{x} - \\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{1/2}{x + 2}", explanation: "Substitute the three constants back." }, { stepNumber: 6, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1/2}{x} - \\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{1/2}{x + 2}\\right]dx = \\displaystyle\\frac{1}{2}\\ln|x| - \\ln|x + 1| + \\displaystyle\\frac{1}{2}\\ln|x + 2| + C", explanation: "Each piece is a constant over a linear factor — \\(\\ln\\) antiderivative." }, { stepNumber: 7, description: "Combine using log laws (optional).", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{x(x + 2)}{(x + 1)^2}\\right| + C", explanation: "\\(\\displaystyle\\frac{1}{2}\\ln|x| + \\displaystyle\\frac{1}{2}\\ln|x + 2| - \\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln|x(x + 2)| - \\ln|x + 1|\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln|x| - \\ln|x + 1| + \\displaystyle\\frac{1}{2}\\ln|x + 2|\\right] = \\displaystyle\\frac{1/2}{x} - \\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{1/2}{x + 2} = \\displaystyle\\frac{1}{x(x + 1)(x + 2)}\\;\\checkmark", explanation: "Combining over a common denominator restores the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln|x| - \\ln|x + 1| + \\displaystyle\\frac{1}{2}\\ln|x + 2| + C\\)." } },
  { id: "y2in7-033", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 33", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2x}{x^2 + 6x + 5}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + 6x + 5 = (x + 1)(x + 5)", explanation: "Numbers multiplying to \\(5\\) and adding to \\(6\\): \\(1\\) and \\(5\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{2x}{(x + 1)(x + 5)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 5}", explanation: "Distinct linear factors." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "2x = A(x + 5) + B(x + 1);\\;x = -1:-2 = 4A\\Rightarrow A = -\\displaystyle\\frac{1}{2};\\;x = -5:-10 = -4B\\Rightarrow B = \\displaystyle\\frac{5}{2}", explanation: "Cover-up at each root." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2x}{(x + 1)(x + 5)} = -\\displaystyle\\frac{1/2}{x + 1} + \\displaystyle\\frac{5/2}{x + 5}", explanation: "Plug constants back in." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[-\\displaystyle\\frac{1/2}{x + 1} + \\displaystyle\\frac{5/2}{x + 5}\\right]dx = -\\displaystyle\\frac{1}{2}\\ln|x + 1| + \\displaystyle\\frac{5}{2}\\ln|x + 5| + C", explanation: "Each piece is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{2}\\ln|x + 1| + \\displaystyle\\frac{5}{2}\\ln|x + 5|\\right] = -\\displaystyle\\frac{1/2}{x + 1} + \\displaystyle\\frac{5/2}{x + 5} = \\displaystyle\\frac{2x}{(x + 1)(x + 5)}\\;\\checkmark", explanation: "Common denominator: \\(-\\displaystyle\\frac{1}{2}(x + 5) + \\displaystyle\\frac{5}{2}(x + 1) = 2x\\)." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{2}\\ln|x + 1| + \\displaystyle\\frac{5}{2}\\ln|x + 5| + C\\)." } },
  { id: "y2in7-034", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 34", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2x - 1}{\\left(x - 1\\right)\\left(x - 2\\right)\\left(x - 3\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Three distinct linear factors.", workingLatex: "(x - 1),\\;(x - 2),\\;(x - 3)", explanation: "Standard three-factor decomposition applies." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{2x - 1}{(x - 1)(x - 2)(x - 3)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x - 2} + \\displaystyle\\frac{C}{x - 3}", explanation: "Three constants for three distinct linear factors." }, { stepNumber: 3, description: "Combine over a common denominator.", workingLatex: "2x - 1 = A(x - 2)(x - 3) + B(x - 1)(x - 3) + C(x - 1)(x - 2)", explanation: "Multiply both sides by the full denominator." }, { stepNumber: 4, description: "Cover-up at each root.", workingLatex: "x = 1:1 = A(-1)(-2) = 2A\\Rightarrow A = \\displaystyle\\frac{1}{2};\\;x = 2:3 = B(1)(-1) = -B\\Rightarrow B = -3;\\;x = 3:5 = C(2)(1) = 2C\\Rightarrow C = \\displaystyle\\frac{5}{2}", explanation: "Each substitution isolates one constant." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2x - 1}{(x - 1)(x - 2)(x - 3)} = \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{5/2}{x - 3}", explanation: "Substitute the three constants." }, { stepNumber: 6, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{5/2}{x - 3}\\right]dx = \\displaystyle\\frac{1}{2}\\ln|x - 1| - 3\\ln|x - 2| + \\displaystyle\\frac{5}{2}\\ln|x - 3| + C", explanation: "Three standard \\(\\ln\\) antiderivatives." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln|x - 1| - 3\\ln|x - 2| + \\displaystyle\\frac{5}{2}\\ln|x - 3|\\right] = \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{5/2}{x - 3}\\;\\checkmark", explanation: "Recombining over the common denominator yields \\((2x - 1)/[(x - 1)(x - 2)(x - 3)]\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln|x - 1| - 3\\ln|x - 2| + \\displaystyle\\frac{5}{2}\\ln|x - 3| + C\\)." } },
  // ── More improper ────
  { id: "y2in7-035", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 35", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x}{x - 2}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise improper rational.", workingLatex: "\\deg(x) = \\deg(x - 2) = 1", explanation: "Top and bottom have equal degree, so polynomial long division is needed before partial fractions." }, { stepNumber: 2, description: "Do the long division.", workingLatex: "\\displaystyle\\frac{x}{x - 2} = \\displaystyle\\frac{(x - 2) + 2}{x - 2} = 1 + \\displaystyle\\frac{2}{x - 2}", explanation: "Write the numerator as the denominator plus a remainder." }, { stepNumber: 3, description: "Integrate the constant piece.", workingLatex: "\\displaystyle\\int 1\\,dx = x", explanation: "Power rule for \\(x^0\\)." }, { stepNumber: 4, description: "Integrate the remainder.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2}{x - 2}\\,dx = 2\\ln|x - 2|", explanation: "\\(\\displaystyle\\int \\displaystyle\\frac{1}{x - a}\\,dx = \\ln|x - a|\\)." }, { stepNumber: 5, description: "Combine and add the constant.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x - 2}\\,dx = x + 2\\ln|x - 2| + C", explanation: "Sum of two pieces, single constant of integration." } ], finalAnswer: "\\(x + 2\\ln|x - 2| + C\\)." } },
  { id: "y2in7-036", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 36", difficulty: "Foundation", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3x + 5}{x + 1}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Improper rational — divide first.", workingLatex: "\\deg(3x + 5) = \\deg(x + 1) = 1", explanation: "Equal degree, so polynomial division precedes partial fractions." }, { stepNumber: 2, description: "Carry out the division.", workingLatex: "3x + 5 = 3(x + 1) + 2\\;\\Rightarrow\\;\\displaystyle\\frac{3x + 5}{x + 1} = 3 + \\displaystyle\\frac{2}{x + 1}", explanation: "Split the numerator as a multiple of the denominator plus a remainder." }, { stepNumber: 3, description: "Integrate the constant.", workingLatex: "\\displaystyle\\int 3\\,dx = 3x", explanation: "Direct power rule." }, { stepNumber: 4, description: "Integrate the remainder.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2}{x + 1}\\,dx = 2\\ln|x + 1|", explanation: "Standard \\(\\ln\\) antiderivative." }, { stepNumber: 5, description: "Combine.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{3x + 5}{x + 1}\\,dx = 3x + 2\\ln|x + 1| + C", explanation: "Sum of the two pieces plus the constant of integration." } ], finalAnswer: "\\(3x + 2\\ln|x + 1| + C\\)." } },
  { id: "y2in7-037", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 37", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2 - 4}{x + 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Improper rational — divide first.", workingLatex: "\\deg(x^2 - 4) = 2 > 1 = \\deg(x + 1)", explanation: "Numerator degree exceeds denominator, so we do polynomial long division." }, { stepNumber: 2, description: "Long division.", workingLatex: "x^2 - 4 = (x + 1)(x - 1) - 3\\;\\Rightarrow\\;\\displaystyle\\frac{x^2 - 4}{x + 1} = x - 1 - \\displaystyle\\frac{3}{x + 1}", explanation: "Quotient \\(x - 1\\) with remainder \\(-3\\). Verify: \\((x + 1)(x - 1) = x^2 - 1\\), so \\(x^2 - 4 = x^2 - 1 - 3\\). \\(\\checkmark\\)" }, { stepNumber: 3, description: "Integrate the polynomial part.", workingLatex: "\\displaystyle\\int (x - 1)\\,dx = \\displaystyle\\frac{x^2}{2} - x", explanation: "Power rule term-by-term." }, { stepNumber: 4, description: "Integrate the remainder.", workingLatex: "\\displaystyle\\int -\\displaystyle\\frac{3}{x + 1}\\,dx = -3\\ln|x + 1|", explanation: "Constant over linear gives \\(\\ln\\) of the linear factor." }, { stepNumber: 5, description: "Combine.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x^2 - 4}{x + 1}\\,dx = \\displaystyle\\frac{x^2}{2} - x - 3\\ln|x + 1| + C", explanation: "Sum the pieces and add a single constant." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{x^2}{2} - x - 3\\ln|x + 1|\\right] = x - 1 - \\displaystyle\\frac{3}{x + 1} = \\displaystyle\\frac{(x - 1)(x + 1) - 3}{x + 1} = \\displaystyle\\frac{x^2 - 4}{x + 1}\\;\\checkmark", explanation: "Recombining over the common denominator restores the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{x^2}{2} - x - 3\\ln|x + 1| + C\\)." } },
  { id: "y2in7-038", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 38", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2 + 3x - 1}{x^2 - 1}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper"], workedSolution: { steps: [ { stepNumber: 1, description: "Improper rational — divide first.", workingLatex: "\\deg(x^2 + 3x - 1) = \\deg(x^2 - 1) = 2", explanation: "Equal degree, so long division is required." }, { stepNumber: 2, description: "Divide.", workingLatex: "x^2 + 3x - 1 = 1\\cdot(x^2 - 1) + 3x\\;\\Rightarrow\\;\\displaystyle\\frac{x^2 + 3x - 1}{x^2 - 1} = 1 + \\displaystyle\\frac{3x}{x^2 - 1}", explanation: "Subtract \\(x^2 - 1\\) from \\(x^2 + 3x - 1\\) to get remainder \\(3x\\)." }, { stepNumber: 3, description: "Factor the remaining denominator.", workingLatex: "x^2 - 1 = (x - 1)(x + 1)", explanation: "Difference of squares." }, { stepNumber: 4, description: "Decompose the proper part.", workingLatex: "\\displaystyle\\frac{3x}{(x - 1)(x + 1)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 1};\\;3x = A(x + 1) + B(x - 1)", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 5, description: "Cover-up.", workingLatex: "x = 1:3 = 2A\\Rightarrow A = \\displaystyle\\frac{3}{2};\\;x = -1:-3 = -2B\\Rightarrow B = \\displaystyle\\frac{3}{2}", explanation: "Substitute each root." }, { stepNumber: 6, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{x^2 + 3x - 1}{x^2 - 1} = 1 + \\displaystyle\\frac{3/2}{x - 1} + \\displaystyle\\frac{3/2}{x + 1}", explanation: "Combine the polynomial \\(1\\) with the two partial fractions." }, { stepNumber: 7, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[1 + \\displaystyle\\frac{3/2}{x - 1} + \\displaystyle\\frac{3/2}{x + 1}\\right]dx = x + \\displaystyle\\frac{3}{2}\\ln|x - 1| + \\displaystyle\\frac{3}{2}\\ln|x + 1| + C", explanation: "Polynomial via power rule; each fraction is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 8, description: "Combine the logs.", workingLatex: "= x + \\displaystyle\\frac{3}{2}\\ln|(x - 1)(x + 1)| + C = x + \\displaystyle\\frac{3}{2}\\ln|x^2 - 1| + C", explanation: "\\(\\ln a + \\ln b = \\ln(ab)\\), and \\((x - 1)(x + 1) = x^2 - 1\\)." }, { stepNumber: 9, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[x + \\displaystyle\\frac{3}{2}\\ln|x^2 - 1|\\right] = 1 + \\displaystyle\\frac{3}{2}\\cdot\\displaystyle\\frac{2x}{x^2 - 1} = 1 + \\displaystyle\\frac{3x}{x^2 - 1} = \\displaystyle\\frac{x^2 + 3x - 1}{x^2 - 1}\\;\\checkmark", explanation: "Restores the integrand exactly." } ], finalAnswer: "\\(x + \\displaystyle\\frac{3}{2}\\ln|x^2 - 1| + C\\)." } },
  // ── More repeated ────
  { id: "y2in7-039", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 39", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x + 2}{x(x - 1)^2}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify factors.", workingLatex: "x\\;\\text{(linear)},\\;(x - 1)^2\\;\\text{(repeated linear)}", explanation: "A repeated factor needs one term per power up to its multiplicity." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{x + 2}{x(x - 1)^2} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x - 1} + \\displaystyle\\frac{C}{(x - 1)^2}", explanation: "Distinct linear \\(x\\) and repeated linear \\((x - 1)^2\\) — the repeated factor contributes two terms." }, { stepNumber: 3, description: "Combine over a common denominator.", workingLatex: "x + 2 = A(x - 1)^2 + Bx(x - 1) + Cx", explanation: "Multiply both sides by \\(x(x - 1)^2\\)." }, { stepNumber: 4, description: "Cover-up the unique roots; compare a coefficient for \\(B\\).", workingLatex: "x = 0:2 = A\\Rightarrow A = 2;\\;x = 1:3 = C;\\;x^2\\;\\text{coef}:0 = A + B\\Rightarrow B = -2", explanation: "Substituting \\(x = 0\\) and \\(x = 1\\) gives \\(A\\) and \\(C\\); matching the \\(x^2\\) coefficient on both sides (LHS has none) gives \\(B\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x + 2}{x(x - 1)^2} = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{3}{(x - 1)^2}", explanation: "Substitute the three constants back." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{3}{(x - 1)^2}\\right]dx = 2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{3}{x - 1} + C", explanation: "Logs for the first two terms; for the squared term, \\(\\displaystyle\\int (x - 1)^{-2}\\,dx = -(x - 1)^{-1}\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{3}{x - 1}\\right] = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x - 1} + \\displaystyle\\frac{3}{(x - 1)^2} = \\displaystyle\\frac{x + 2}{x(x - 1)^2}\\;\\checkmark", explanation: "Recovers the integrand exactly." } ], finalAnswer: "\\(2\\ln|x| - 2\\ln|x - 1| - \\displaystyle\\frac{3}{x - 1} + C\\)." } },
  { id: "y2in7-040", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 40", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{5x + 1}{\\left(x + 2\\right)^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Repeated linear factor in denominator.", workingLatex: "(x + 2)^2", explanation: "We can either decompose into \\(\\displaystyle\\frac{A}{x + 2} + \\displaystyle\\frac{B}{(x + 2)^2}\\) or rewrite the numerator in terms of \\((x + 2)\\) directly." }, { stepNumber: 2, description: "Rewrite the numerator in terms of \\(x + 2\\).", workingLatex: "5x + 1 = 5(x + 2) - 9", explanation: "\\(5(x + 2) = 5x + 10\\), so we subtract \\(9\\) to recover \\(5x + 1\\)." }, { stepNumber: 3, description: "Split the integrand.", workingLatex: "\\displaystyle\\frac{5x + 1}{(x + 2)^2} = \\displaystyle\\frac{5(x + 2) - 9}{(x + 2)^2} = \\displaystyle\\frac{5}{x + 2} - \\displaystyle\\frac{9}{(x + 2)^2}", explanation: "Distribute the denominator across the rewritten numerator." }, { stepNumber: 4, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{5}{x + 2} - \\displaystyle\\frac{9}{(x + 2)^2}\\right]dx = 5\\ln|x + 2| + \\displaystyle\\frac{9}{x + 2} + C", explanation: "First piece: \\(\\ln\\). Second: \\(\\displaystyle\\int (x + 2)^{-2}\\,dx = -(x + 2)^{-1}\\), so with the \\(-9\\) coefficient we get \\(+9/(x + 2)\\)." }, { stepNumber: 5, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[5\\ln|x + 2| + \\displaystyle\\frac{9}{x + 2}\\right] = \\displaystyle\\frac{5}{x + 2} - \\displaystyle\\frac{9}{(x + 2)^2} = \\displaystyle\\frac{5(x + 2) - 9}{(x + 2)^2} = \\displaystyle\\frac{5x + 1}{(x + 2)^2}\\;\\checkmark", explanation: "Combining over the common denominator recovers the integrand." } ], finalAnswer: "\\(5\\ln|x + 2| + \\displaystyle\\frac{9}{x + 2} + C\\)." } },
  { id: "y2in7-041", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 41", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3}{x^2\\left(x - 2\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Identify factors.", workingLatex: "x^2\\;\\text{(repeated linear)},\\;(x - 2)\\;\\text{(linear)}", explanation: "The repeated factor \\(x^2\\) contributes two terms: one over \\(x\\) and one over \\(x^2\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{3}{x^2(x - 2)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x^2} + \\displaystyle\\frac{C}{x - 2}", explanation: "Standard form for a squared linear factor plus a distinct linear factor." }, { stepNumber: 3, description: "Combine over the common denominator.", workingLatex: "3 = Ax(x - 2) + B(x - 2) + Cx^2", explanation: "Multiply both sides by \\(x^2(x - 2)\\)." }, { stepNumber: 4, description: "Solve for the constants.", workingLatex: "x = 0:3 = -2B\\Rightarrow B = -\\displaystyle\\frac{3}{2};\\;x = 2:3 = 4C\\Rightarrow C = \\displaystyle\\frac{3}{4};\\;x^2\\;\\text{coef}:0 = A + C\\Rightarrow A = -\\displaystyle\\frac{3}{4}", explanation: "Cover-up at \\(x = 0\\) and \\(x = 2\\), then match the \\(x^2\\) coefficient (the LHS has none) to pin down \\(A\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{3}{x^2(x - 2)} = -\\displaystyle\\frac{3/4}{x} - \\displaystyle\\frac{3/2}{x^2} + \\displaystyle\\frac{3/4}{x - 2}", explanation: "Substitute the three constants." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left[-\\displaystyle\\frac{3/4}{x} - \\displaystyle\\frac{3/2}{x^2} + \\displaystyle\\frac{3/4}{x - 2}\\right]dx = -\\displaystyle\\frac{3}{4}\\ln|x| + \\displaystyle\\frac{3}{2x} + \\displaystyle\\frac{3}{4}\\ln|x - 2| + C", explanation: "Logs for the \\(1/x\\) and \\(1/(x - 2)\\) terms; for \\(\\displaystyle\\int -\\displaystyle\\frac{3}{2}x^{-2}\\,dx = +\\displaystyle\\frac{3}{2}x^{-1} = 3/(2x)\\)." }, { stepNumber: 7, description: "Combine the logs (optional).", workingLatex: "= \\displaystyle\\frac{3}{4}\\ln\\!\\left|\\displaystyle\\frac{x - 2}{x}\\right| + \\displaystyle\\frac{3}{2x} + C", explanation: "\\(-\\displaystyle\\frac{3}{4}\\ln|x| + \\displaystyle\\frac{3}{4}\\ln|x - 2| = \\displaystyle\\frac{3}{4}\\ln|(x - 2)/x|\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{3}{4}\\ln|x| + \\displaystyle\\frac{3}{2x} + \\displaystyle\\frac{3}{4}\\ln|x - 2|\\right] = -\\displaystyle\\frac{3/4}{x} - \\displaystyle\\frac{3/2}{x^2} + \\displaystyle\\frac{3/4}{x - 2} = \\displaystyle\\frac{3}{x^2(x - 2)}\\;\\checkmark", explanation: "Recombining the three fractions gives the original integrand." } ], finalAnswer: "\\(-\\displaystyle\\frac{3}{4}\\ln|x| + \\displaystyle\\frac{3}{2x} + \\displaystyle\\frac{3}{4}\\ln|x - 2| + C\\)." } },
  // ── Mixed ────
  { id: "y2in7-042", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 42", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{9 - x^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "9 - x^2 = (3 - x)(3 + x)", explanation: "Difference of squares: \\(a^2 - b^2 = (a - b)(a + b)\\) with \\(a = 3\\), \\(b = x\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{1}{(3 - x)(3 + x)} = \\displaystyle\\frac{A}{3 - x} + \\displaystyle\\frac{B}{3 + x}", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "1 = A(3 + x) + B(3 - x);\\;x = 3:1 = 6A\\Rightarrow A = \\displaystyle\\frac{1}{6};\\;x = -3:1 = 6B\\Rightarrow B = \\displaystyle\\frac{1}{6}", explanation: "Substitute each root to isolate the constants." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{9 - x^2} = \\displaystyle\\frac{1/6}{3 - x} + \\displaystyle\\frac{1/6}{3 + x}", explanation: "Plug constants back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1/6}{3 - x}\\,dx = -\\displaystyle\\frac{1}{6}\\ln|3 - x|;\\quad \\displaystyle\\int \\displaystyle\\frac{1/6}{3 + x}\\,dx = \\displaystyle\\frac{1}{6}\\ln|3 + x|", explanation: "Note the sign on the first: the derivative of \\(3 - x\\) is \\(-1\\), so \\(\\displaystyle\\int \\displaystyle\\frac{1}{3 - x}\\,dx = -\\ln|3 - x|\\)." }, { stepNumber: 6, description: "Combine.", workingLatex: "= \\displaystyle\\frac{1}{6}\\ln|3 + x| - \\displaystyle\\frac{1}{6}\\ln|3 - x| + C = \\displaystyle\\frac{1}{6}\\ln\\!\\left|\\displaystyle\\frac{3 + x}{3 - x}\\right| + C", explanation: "\\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{6}\\ln\\!\\left|\\displaystyle\\frac{3 + x}{3 - x}\\right|\\right] = \\displaystyle\\frac{1}{6}\\!\\left(\\displaystyle\\frac{1}{3 + x} + \\displaystyle\\frac{1}{3 - x}\\right) = \\displaystyle\\frac{1}{6}\\cdot\\displaystyle\\frac{6}{9 - x^2} = \\displaystyle\\frac{1}{9 - x^2}\\;\\checkmark", explanation: "Recovers the integrand exactly." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{6}\\ln\\left|\\displaystyle\\frac{3 + x}{3 - x}\\right| + C\\)." } },
  { id: "y2in7-043", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 43", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x - 3}{x^2 + 2x - 3}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + 2x - 3 = (x + 3)(x - 1)", explanation: "Numbers multiplying to \\(-3\\) and adding to \\(2\\): \\(3\\) and \\(-1\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{x - 3}{(x + 3)(x - 1)} = \\displaystyle\\frac{A}{x + 3} + \\displaystyle\\frac{B}{x - 1}", explanation: "Distinct linear factors." }, { stepNumber: 3, description: "Combine over the common denominator.", workingLatex: "x - 3 = A(x - 1) + B(x + 3)", explanation: "Multiply both sides by \\((x + 3)(x - 1)\\)." }, { stepNumber: 4, description: "Cover-up.", workingLatex: "x = 1:-2 = 4B\\Rightarrow B = -\\displaystyle\\frac{1}{2};\\;x = -3:-6 = -4A\\Rightarrow A = \\displaystyle\\frac{3}{2}", explanation: "Substitute each root in turn." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x - 3}{(x + 3)(x - 1)} = \\displaystyle\\frac{3/2}{x + 3} - \\displaystyle\\frac{1/2}{x - 1}", explanation: "Plug constants back." }, { stepNumber: 6, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{3/2}{x + 3} - \\displaystyle\\frac{1/2}{x - 1}\\right]dx = \\displaystyle\\frac{3}{2}\\ln|x + 3| - \\displaystyle\\frac{1}{2}\\ln|x - 1| + C", explanation: "Each piece is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{3}{2}\\ln|x + 3| - \\displaystyle\\frac{1}{2}\\ln|x - 1|\\right] = \\displaystyle\\frac{3/2}{x + 3} - \\displaystyle\\frac{1/2}{x - 1} = \\displaystyle\\frac{\\displaystyle\\frac{3}{2}(x - 1) - \\displaystyle\\frac{1}{2}(x + 3)}{(x + 3)(x - 1)} = \\displaystyle\\frac{x - 3}{(x + 3)(x - 1)}\\;\\checkmark", explanation: "Common denominator: \\(\\displaystyle\\frac{3}{2}(x - 1) - \\displaystyle\\frac{1}{2}(x + 3) = \\displaystyle\\frac{3x - 3 - x - 3}{2} = x - 3\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{3}{2}\\ln|x + 3| - \\displaystyle\\frac{1}{2}\\ln|x - 1| + C\\)." } },
  { id: "y2in7-044", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 44", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{4}{x^2 + 2x}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 + 2x = x(x + 2)", explanation: "Take out the common factor \\(x\\)." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{4}{x(x + 2)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 2}", explanation: "Two distinct linear factors." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "4 = A(x + 2) + Bx;\\;x = 0:4 = 2A\\Rightarrow A = 2;\\;x = -2:4 = -2B\\Rightarrow B = -2", explanation: "Cover-up at each root." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{4}{x(x + 2)} = \\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x + 2}", explanation: "Substitute constants back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{2}{x} - \\displaystyle\\frac{2}{x + 2}\\right]dx = 2\\ln|x| - 2\\ln|x + 2| + C", explanation: "Each piece is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 6, description: "Combine.", workingLatex: "= 2\\ln\\!\\left|\\displaystyle\\frac{x}{x + 2}\\right| + C", explanation: "\\(\\ln a - \\ln b = \\ln(a/b)\\); factor out the 2." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2\\ln\\!\\left|\\displaystyle\\frac{x}{x + 2}\\right|\\right] = 2\\!\\left(\\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 2}\\right) = \\displaystyle\\frac{2 \\cdot 2}{x(x + 2)} = \\displaystyle\\frac{4}{x(x + 2)}\\;\\checkmark", explanation: "Common denominator: \\(\\displaystyle\\frac{1}{x} - \\displaystyle\\frac{1}{x + 2} = \\displaystyle\\frac{2}{x(x + 2)}\\)." } ], finalAnswer: "\\(2\\ln\\left|\\displaystyle\\frac{x}{x + 2}\\right| + C\\)." } },
  { id: "y2in7-045", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 45", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{5x - 2}{x^2 - 4}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 4 = (x - 2)(x + 2)", explanation: "Difference of squares." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{5x - 2}{(x - 2)(x + 2)} = \\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x + 2}", explanation: "Distinct linear factors." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "5x - 2 = A(x + 2) + B(x - 2);\\;x = 2:8 = 4A\\Rightarrow A = 2;\\;x = -2:-12 = -4B\\Rightarrow B = 3", explanation: "Cover-up at each root." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{5x - 2}{(x - 2)(x + 2)} = \\displaystyle\\frac{2}{x - 2} + \\displaystyle\\frac{3}{x + 2}", explanation: "Plug constants back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{2}{x - 2} + \\displaystyle\\frac{3}{x + 2}\\right]dx = 2\\ln|x - 2| + 3\\ln|x + 2| + C", explanation: "Each piece is a standard \\(\\ln\\) antiderivative." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2\\ln|x - 2| + 3\\ln|x + 2|\\right] = \\displaystyle\\frac{2}{x - 2} + \\displaystyle\\frac{3}{x + 2} = \\displaystyle\\frac{2(x + 2) + 3(x - 2)}{(x - 2)(x + 2)} = \\displaystyle\\frac{5x - 2}{x^2 - 4}\\;\\checkmark", explanation: "Common denominator restores the integrand." } ], finalAnswer: "\\(2\\ln|x - 2| + 3\\ln|x + 2| + C\\)." } },
  // ── More definite ────
  { id: "y2in7-046", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 46", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\displaystyle\\frac{1}{\\left(x + 1\\right)\\left(x + 2\\right)}\\,dx \\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{1}{(x + 1)(x + 2)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 2, description: "Solve for \\(A,\\,B\\).", workingLatex: "1 = A(x + 2) + B(x + 1);\\;x = -1:A = 1;\\;x = -2:B = -1", explanation: "Cover-up at each root." }, { stepNumber: 3, description: "Decomposition.", workingLatex: "\\displaystyle\\frac{1}{(x + 1)(x + 2)} = \\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{x + 2}", explanation: "Substitute constants back." }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1}{x + 1} - \\displaystyle\\frac{1}{x + 2}\\right]dx = \\ln|x + 1| - \\ln|x + 2| = \\ln\\!\\left|\\displaystyle\\frac{x + 1}{x + 2}\\right|", explanation: "Two standard \\(\\ln\\) antiderivatives, combined via log laws." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\left[\\ln\\!\\left|\\displaystyle\\frac{x + 1}{x + 2}\\right|\\right]_0^1 = \\ln\\!\\left(\\displaystyle\\frac{2}{3}\\right) - \\ln\\!\\left(\\displaystyle\\frac{1}{2}\\right)", explanation: "At \\(x = 1\\): \\(\\ln(2/3)\\). At \\(x = 0\\): \\(\\ln(1/2)\\)." }, { stepNumber: 6, description: "Simplify.", workingLatex: "= \\ln\\!\\left(\\displaystyle\\frac{2/3}{1/2}\\right) = \\ln\\!\\left(\\displaystyle\\frac{4}{3}\\right)", explanation: "Divide the fractions to combine the logs." } ], finalAnswer: "\\(\\ln\\displaystyle\\frac{4}{3}\\)." } },
  { id: "y2in7-047", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 47", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_2^4 \\displaystyle\\frac{x}{\\left(x - 1\\right)\\left(x + 1\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{x}{(x - 1)(x + 1)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 1}", explanation: "Two distinct linear factors." }, { stepNumber: 2, description: "Solve for \\(A,\\,B\\).", workingLatex: "x = A(x + 1) + B(x - 1);\\;x = 1:1 = 2A\\Rightarrow A = \\displaystyle\\frac{1}{2};\\;x = -1:-1 = -2B\\Rightarrow B = \\displaystyle\\frac{1}{2}", explanation: "Cover-up at each root." }, { stepNumber: 3, description: "Decomposition.", workingLatex: "\\displaystyle\\frac{x}{(x - 1)(x + 1)} = \\displaystyle\\frac{1/2}{x - 1} + \\displaystyle\\frac{1/2}{x + 1}", explanation: "Substitute constants back." }, { stepNumber: 4, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1/2}{x - 1} + \\displaystyle\\frac{1/2}{x + 1}\\right]dx = \\displaystyle\\frac{1}{2}\\ln|x - 1| + \\displaystyle\\frac{1}{2}\\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln|x^2 - 1|", explanation: "Combine via \\(\\ln a + \\ln b = \\ln(ab)\\) and \\((x - 1)(x + 1) = x^2 - 1\\)." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{1}{2}\\ln|x^2 - 1|\\right]_2^4 = \\displaystyle\\frac{1}{2}\\ln 15 - \\displaystyle\\frac{1}{2}\\ln 3", explanation: "At \\(x = 4\\): \\(x^2 - 1 = 15\\). At \\(x = 2\\): \\(x^2 - 1 = 3\\)." }, { stepNumber: 6, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln\\!\\left(\\displaystyle\\frac{15}{3}\\right) = \\displaystyle\\frac{1}{2}\\ln 5", explanation: "Divide \\(15/3 = 5\\) inside the log." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln 5\\)." } },
  { id: "y2in7-048", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 48", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^{\\frac{1}{2}} \\displaystyle\\frac{1}{1 - x^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "1 - x^2 = (1 - x)(1 + x)", explanation: "Difference of squares." }, { stepNumber: 2, description: "Set up partial fractions.", workingLatex: "\\displaystyle\\frac{1}{(1 - x)(1 + x)} = \\displaystyle\\frac{A}{1 - x} + \\displaystyle\\frac{B}{1 + x}", explanation: "Distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Solve for \\(A,\\,B\\).", workingLatex: "1 = A(1 + x) + B(1 - x);\\;x = 1:1 = 2A\\Rightarrow A = \\displaystyle\\frac{1}{2};\\;x = -1:1 = 2B\\Rightarrow B = \\displaystyle\\frac{1}{2}", explanation: "Cover-up at the two roots." }, { stepNumber: 4, description: "Decomposition.", workingLatex: "\\displaystyle\\frac{1}{1 - x^2} = \\displaystyle\\frac{1/2}{1 - x} + \\displaystyle\\frac{1/2}{1 + x}", explanation: "Substitute constants back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left[\\displaystyle\\frac{1/2}{1 - x} + \\displaystyle\\frac{1/2}{1 + x}\\right]dx = -\\displaystyle\\frac{1}{2}\\ln|1 - x| + \\displaystyle\\frac{1}{2}\\ln|1 + x| = \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right|", explanation: "Note \\(\\displaystyle\\int \\displaystyle\\frac{1}{1 - x}\\,dx = -\\ln|1 - x|\\) (derivative of \\(1 - x\\) is \\(-1\\))." }, { stepNumber: 6, description: "Apply the limits 0 to \\(\\displaystyle\\frac{1}{2}\\).", workingLatex: "\\left[\\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right|\\right]_0^{1/2} = \\displaystyle\\frac{1}{2}\\ln\\!\\left(\\displaystyle\\frac{3/2}{1/2}\\right) - \\displaystyle\\frac{1}{2}\\ln 1", explanation: "At \\(x = \\displaystyle\\frac{1}{2}\\): \\((1 + \\displaystyle\\frac{1}{2})/(1 - \\displaystyle\\frac{1}{2}) = (3/2)/(1/2) = 3\\). At \\(x = 0\\): \\(\\ln 1 = 0\\)." }, { stepNumber: 7, description: "Simplify.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln 3", explanation: "Final closed-form answer." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln 3\\)." } },
  { id: "y2in7-049", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 49", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\displaystyle\\frac{x^2}{x + 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "improper", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Recognise an improper rational.", workingLatex: "\\deg(\\text{num}) = 2 \\ge 1 = \\deg(\\text{den})", explanation: "Before partial fractions we always check degrees. Here the numerator's degree is at least the denominator's, so the rational function is improper — polynomial long division must come first to peel off a polynomial part." }, { stepNumber: 2, description: "Polynomial long division.", workingLatex: "\\displaystyle\\frac{x^2}{x + 1} = x - 1 + \\displaystyle\\frac{1}{x + 1}", explanation: "Divide \\(x^2\\) by \\(x+1\\): \\(x^2 = (x+1)\\cdot x - x\\); continue \\(-x = (x+1)\\cdot(-1) + 1\\). So quotient \\(x - 1\\), remainder \\(1\\). The denominator is already linear so no further partial fractions are needed." }, { stepNumber: 3, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int\\!\\left(x - 1 + \\displaystyle\\frac{1}{x + 1}\\right)dx = \\displaystyle\\frac{x^2}{2} - x + \\ln|x + 1| + C", explanation: "Power rule on \\(x\\) and on the constant \\(-1\\); the last piece is the standard log \\(\\int \\displaystyle\\frac{1}{x+1}\\,dx = \\ln|x+1|\\)." }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{x^2}{2} - x + \\ln|x + 1|\\right]_0^1 = \\left(\\displaystyle\\frac{1}{2} - 1 + \\ln 2\\right) - \\left(0 - 0 + \\ln 1\\right)", explanation: "Evaluate the antiderivative at the upper and lower limits and subtract. Recall \\(\\ln 1 = 0\\)." }, { stepNumber: 5, description: "Simplify.", workingLatex: "= \\ln 2 - \\displaystyle\\frac{1}{2}", explanation: "Collect the constant terms: \\(\\displaystyle\\frac{1}{2} - 1 = -\\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{x^2}{2} - x + \\ln|x + 1|\\right] = x - 1 + \\displaystyle\\frac{1}{x + 1} = \\displaystyle\\frac{(x-1)(x+1) + 1}{x+1} = \\displaystyle\\frac{x^2}{x+1}\\;\\checkmark", explanation: "Recovers the original integrand exactly — the antiderivative is verified." } ], finalAnswer: "\\(\\ln 2 - \\displaystyle\\frac{1}{2}\\)." } },
  { id: "y2in7-050", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 50", difficulty: "Challenge", questionText: "Evaluate \\( \\displaystyle\\int_1^2 \\displaystyle\\frac{1}{x^2\\left(x + 1\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated", "definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Choose the decomposition form.", workingLatex: "\\displaystyle\\frac{1}{x^2(x + 1)} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x^2} + \\displaystyle\\frac{C}{x + 1}", explanation: "Distinct linear factor \\(x+1\\) gives a single term; the repeated factor \\(x^2\\) needs two terms — one over \\(x\\) and one over \\(x^2\\) — because the partial-fraction template uses every power up to the repeat." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "1 = Ax(x + 1) + B(x + 1) + Cx^2", explanation: "Multiply both sides by \\(x^2(x+1)\\). This identity must hold for every \\(x\\), which gives us levers to pin down \\(A, B, C\\)." }, { stepNumber: 3, description: "Substitute convenient values.", workingLatex: "x = 0:\\;1 = B \\;\\Rightarrow\\; B = 1;\\quad x = -1:\\;1 = C \\;\\Rightarrow\\; C = 1", explanation: "The roots of the original denominator factors collapse two of the three unknown terms each time, isolating \\(B\\) and \\(C\\)." }, { stepNumber: 4, description: "Find \\(A\\) by comparing coefficients of \\(x^2\\).", workingLatex: "0 = A + C \\;\\Rightarrow\\; A = -1", explanation: "Match the \\(x^2\\) coefficient on both sides of the identity: LHS has none, RHS has \\(A + C\\). With \\(C = 1\\), \\(A = -1\\)." }, { stepNumber: 5, description: "Write the full decomposition.", workingLatex: "\\displaystyle\\frac{1}{x^2(x + 1)} = -\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} + \\displaystyle\\frac{1}{x + 1}", explanation: "Substitute \\(A = -1, B = 1, C = 1\\) back into the template." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left(-\\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} + \\displaystyle\\frac{1}{x + 1}\\right)dx = -\\ln|x| - \\displaystyle\\frac{1}{x} + \\ln|x + 1| + C", explanation: "Standard logs for the two reciprocal terms; \\(\\int x^{-2}\\,dx = -x^{-1}\\) for the middle term." }, { stepNumber: 7, description: "Combine the logs.", workingLatex: "= \\ln\\!\\left|\\displaystyle\\frac{x + 1}{x}\\right| - \\displaystyle\\frac{1}{x} + C", explanation: "Use \\(\\ln a - \\ln b = \\ln(a/b)\\) to tidy. On the interval \\([1,2]\\) both arguments are positive so the bars are optional." }, { stepNumber: 8, description: "Apply the limits.", workingLatex: "\\left[\\ln\\!\\displaystyle\\frac{x + 1}{x} - \\displaystyle\\frac{1}{x}\\right]_1^2 = \\left(\\ln\\!\\displaystyle\\frac{3}{2} - \\displaystyle\\frac{1}{2}\\right) - \\left(\\ln 2 - 1\\right)", explanation: "Plug in \\(x = 2\\) and \\(x = 1\\) and subtract." }, { stepNumber: 9, description: "Simplify the logs and constants.", workingLatex: "= \\ln\\!\\displaystyle\\frac{3}{2} - \\ln 2 + \\displaystyle\\frac{1}{2} = \\ln\\!\\displaystyle\\frac{3}{4} + \\displaystyle\\frac{1}{2}", explanation: "Combine logs: \\(\\ln(3/2) - \\ln 2 = \\ln(3/4)\\). Combine constants: \\(-\\displaystyle\\frac{1}{2} + 1 = \\displaystyle\\frac{1}{2}\\)." }, { stepNumber: 10, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln\\!\\displaystyle\\frac{x+1}{x} - \\displaystyle\\frac{1}{x}\\right] = \\displaystyle\\frac{1}{x+1} - \\displaystyle\\frac{1}{x} + \\displaystyle\\frac{1}{x^2} = \\displaystyle\\frac{1}{x^2(x+1)}\\;\\checkmark", explanation: "Recovers the integrand — the antiderivative is verified." } ], finalAnswer: "\\(\\ln\\displaystyle\\frac{3}{4} + \\displaystyle\\frac{1}{2}\\) (equivalently \\(\\displaystyle\\frac{1}{2} - \\ln\\displaystyle\\frac{4}{3}\\))." } },
  // ── Mixed ────
  { id: "y2in7-051", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 51", difficulty: "Foundation", questionText: "Decompose \\(\\displaystyle\\frac{5}{\\left(x - 2\\right)\\left(x + 3\\right)}\\) into partial fractions (do not integrate).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{5}{(x - 2)(x + 3)} = \\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x + 3}", explanation: "Two distinct linear factors — one constant numerator per factor. This is the simplest partial-fractions pattern." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "5 = A(x + 3) + B(x - 2)", explanation: "Multiply both sides by \\((x-2)(x+3)\\); the equation now holds as an identity in \\(x\\)." }, { stepNumber: 3, description: "Substitute the roots (cover-up).", workingLatex: "x = 2:\\;5 = 5A \\;\\Rightarrow\\; A = 1;\\quad x = -3:\\;5 = -5B \\;\\Rightarrow\\; B = -1", explanation: "Plugging in each root zeroes one unknown at a time — the fastest way to solve for distinct linear factors." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{5}{(x - 2)(x + 3)} = \\displaystyle\\frac{1}{x - 2} - \\displaystyle\\frac{1}{x + 3}", explanation: "Substitute \\(A = 1, B = -1\\) back. Quick sanity check: at \\(x = 0\\), LHS \\(= 5/(-6)\\); RHS \\(= -1/2 - 1/3 = -5/6\\). \\(\\checkmark\\)" } ], finalAnswer: "\\(\\displaystyle\\frac{1}{x - 2} - \\displaystyle\\frac{1}{x + 3}\\)." } },
  { id: "y2in7-052", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 52", difficulty: "Standard", questionText: "Decompose \\(\\displaystyle\\frac{x + 3}{x(x + 1)^2}\\).", marks: 3, examStyle: false, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{x + 3}{x(x + 1)^2} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} + \\displaystyle\\frac{C}{(x + 1)^2}", explanation: "Distinct linear factor \\(x\\) gives one term; repeated factor \\((x+1)^2\\) needs two terms — one over \\(x+1\\) and one over \\((x+1)^2\\) — covering both powers up to the repeat." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "x + 3 = A(x + 1)^2 + Bx(x + 1) + Cx", explanation: "Multiply both sides by \\(x(x+1)^2\\)." }, { stepNumber: 3, description: "Substitute the roots.", workingLatex: "x = 0:\\;3 = A;\\quad x = -1:\\;2 = -C \\;\\Rightarrow\\; C = -2", explanation: "Standard cover-up: each root collapses two of the three terms, isolating \\(A\\) and \\(C\\)." }, { stepNumber: 4, description: "Find \\(B\\) by comparing coefficients of \\(x^2\\).", workingLatex: "0 = A + B \\;\\Rightarrow\\; B = -3", explanation: "The LHS has no \\(x^2\\) term; on the right \\(A(x+1)^2 + Bx(x+1) = (A+B)x^2 + \\ldots\\). With \\(A = 3\\), \\(B = -3\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x + 3}{x(x + 1)^2} = \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{3}{x + 1} - \\displaystyle\\frac{2}{(x + 1)^2}", explanation: "Substitute \\(A = 3, B = -3, C = -2\\) back. Sanity check at \\(x = 1\\): LHS \\(= 4/(1\\cdot 4) = 1\\); RHS \\(= 3 - 3/2 - 1/2 = 1\\). \\(\\checkmark\\)" } ], finalAnswer: "\\(\\displaystyle\\frac{3}{x} - \\displaystyle\\frac{3}{x + 1} - \\displaystyle\\frac{2}{(x + 1)^2}\\)." } },
  { id: "y2in7-053", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 53", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x + 3}{x(x + 1)^2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{x + 3}{x(x + 1)^2} = \\displaystyle\\frac{A}{x} + \\displaystyle\\frac{B}{x + 1} + \\displaystyle\\frac{C}{(x + 1)^2}", explanation: "Linear factor \\(x\\) plus repeated factor \\((x+1)^2\\): one term per distinct factor, with the repeat contributing terms for every power up to its multiplicity." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "x + 3 = A(x + 1)^2 + Bx(x + 1) + Cx", explanation: "Multiply by \\(x(x+1)^2\\); the identity must hold for every \\(x\\)." }, { stepNumber: 3, description: "Solve for \\(A, B, C\\).", workingLatex: "x = 0 \\Rightarrow A = 3;\\;\\; x = -1 \\Rightarrow C = -2;\\;\\; \\text{coeff } x^2:\\,A + B = 0 \\Rightarrow B = -3", explanation: "Substitute the roots, then compare coefficients of \\(x^2\\) for the last unknown." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{x + 3}{x(x + 1)^2} = \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{3}{x + 1} - \\displaystyle\\frac{2}{(x + 1)^2}", explanation: "Substitute \\(A, B, C\\) back into the template." }, { stepNumber: 5, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{3}{x} - \\displaystyle\\frac{3}{x + 1} - \\displaystyle\\frac{2}{(x + 1)^2}\\right)dx = 3\\ln|x| - 3\\ln|x + 1| + \\displaystyle\\frac{2}{x + 1} + C", explanation: "Standard logs for the two reciprocal terms; \\(\\int -2(x+1)^{-2}\\,dx = -2\\cdot[-(x+1)^{-1}] = 2/(x+1)\\)." }, { stepNumber: 6, description: "Combine the logs.", workingLatex: "= 3\\ln\\!\\left|\\displaystyle\\frac{x}{x + 1}\\right| + \\displaystyle\\frac{2}{x + 1} + C", explanation: "\\(3\\ln|x| - 3\\ln|x+1| = 3\\ln|x/(x+1)|\\) — neater closed form." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[3\\ln|x| - 3\\ln|x+1| + \\displaystyle\\frac{2}{x+1}\\right] = \\displaystyle\\frac{3}{x} - \\displaystyle\\frac{3}{x+1} - \\displaystyle\\frac{2}{(x+1)^2} = \\displaystyle\\frac{x+3}{x(x+1)^2}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(3\\ln|x| - 3\\ln|x + 1| + \\displaystyle\\frac{2}{x + 1} + C\\)." } },
  { id: "y2in7-054", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 54", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{7x + 1}{\\left(x - 2\\right)\\left(x + 3\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{7x + 1}{(x - 2)(x + 3)} = \\displaystyle\\frac{A}{x - 2} + \\displaystyle\\frac{B}{x + 3}", explanation: "Two distinct linear factors — one constant numerator each. Note the degree of the numerator (1) is less than the denominator (2), so the rational is already proper." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "7x + 1 = A(x + 3) + B(x - 2)", explanation: "Multiply both sides by \\((x-2)(x+3)\\)." }, { stepNumber: 3, description: "Substitute the roots.", workingLatex: "x = 2:\\;15 = 5A \\;\\Rightarrow\\; A = 3;\\quad x = -3:\\;-20 = -5B \\;\\Rightarrow\\; B = 4", explanation: "Cover-up at each root pins down the two unknowns directly." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{7x + 1}{(x - 2)(x + 3)} = \\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{4}{x + 3}", explanation: "Substitute \\(A = 3, B = 4\\) back." }, { stepNumber: 5, description: "Integrate term by term.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{3}{x - 2} + \\displaystyle\\frac{4}{x + 3}\\right)dx = 3\\ln|x - 2| + 4\\ln|x + 3| + C", explanation: "Each term is in clean \\(f'/f\\) form (the derivatives of \\(x-2\\) and \\(x+3\\) are both \\(1\\)), giving a log." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[3\\ln|x-2| + 4\\ln|x+3|\\right] = \\displaystyle\\frac{3}{x-2} + \\displaystyle\\frac{4}{x+3} = \\displaystyle\\frac{3(x+3) + 4(x-2)}{(x-2)(x+3)} = \\displaystyle\\frac{7x + 1}{(x-2)(x+3)}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(3\\ln|x - 2| + 4\\ln|x + 3| + C\\)." } },
  { id: "y2in7-055", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 55", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2}{3x^2 + 5x - 2}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "3x^2 + 5x - 2 = (3x - 1)(x + 2)", explanation: "Search for roots: trying \\(x = 1/3\\) gives \\(3\\cdot 1/9 + 5/3 - 2 = 1/3 + 5/3 - 2 = 0\\); trying \\(x = -2\\) gives \\(12 - 10 - 2 = 0\\). Both factors confirmed." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{2}{(3x - 1)(x + 2)} = \\displaystyle\\frac{A}{3x - 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Two distinct linear factors — constant numerators. Coefficient on \\(x\\) doesn't matter, only the linearity." }, { stepNumber: 3, description: "Clear denominators.", workingLatex: "2 = A(x + 2) + B(3x - 1)", explanation: "Multiply through by \\((3x-1)(x+2)\\)." }, { stepNumber: 4, description: "Substitute the roots.", workingLatex: "x = \\displaystyle\\frac{1}{3}:\\;2 = \\displaystyle\\frac{7}{3}A \\Rightarrow A = \\displaystyle\\frac{6}{7};\\quad x = -2:\\;2 = -7B \\Rightarrow B = -\\displaystyle\\frac{2}{7}", explanation: "Each root collapses one term, isolating the other unknown." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2}{(3x - 1)(x + 2)} = \\displaystyle\\frac{6/7}{3x - 1} - \\displaystyle\\frac{2/7}{x + 2}", explanation: "Substitute \\(A = 6/7, B = -2/7\\) back." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{6/7}{3x - 1}\\,dx - \\displaystyle\\int \\displaystyle\\frac{2/7}{x + 2}\\,dx = \\displaystyle\\frac{6}{7}\\cdot\\displaystyle\\frac{1}{3}\\ln|3x - 1| - \\displaystyle\\frac{2}{7}\\ln|x + 2| + C", explanation: "For the first integral, \\(\\displaystyle\\frac{d}{dx}(3x-1) = 3\\), so \\(\\int 1/(3x-1)\\,dx = (1/3)\\ln|3x-1|\\). The second is a direct log." }, { stepNumber: 7, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{2}{7}\\ln|3x - 1| - \\displaystyle\\frac{2}{7}\\ln|x + 2| + C = \\displaystyle\\frac{2}{7}\\ln\\!\\left|\\displaystyle\\frac{3x - 1}{x + 2}\\right| + C", explanation: "Combine constants: \\(\\displaystyle\\frac{6}{7}\\cdot\\displaystyle\\frac{1}{3} = \\displaystyle\\frac{2}{7}\\). Then merge logs using \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{2}{7}\\ln|3x-1| - \\displaystyle\\frac{2}{7}\\ln|x+2|\\right] = \\displaystyle\\frac{6/7}{3x-1} - \\displaystyle\\frac{2/7}{x+2} = \\displaystyle\\frac{2}{(3x-1)(x+2)}\\;\\checkmark", explanation: "Common-denominator combination of the two terms recovers \\(\\displaystyle\\frac{2}{(3x-1)(x+2)} = \\displaystyle\\frac{2}{3x^2+5x-2}\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{2}{7}\\ln\\left|\\displaystyle\\frac{3x - 1}{x + 2}\\right| + C\\) (equivalently \\(\\displaystyle\\frac{2}{7}\\ln|3x - 1| - \\displaystyle\\frac{2}{7}\\ln|x + 2| + C\\))." } },
  { id: "y2in7-056", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 56", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{1}{\\left(x - 1\\right)\\left(x + 1\\right)^2}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{1}{(x - 1)(x + 1)^2} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 1} + \\displaystyle\\frac{C}{(x + 1)^2}", explanation: "Distinct linear factor \\(x-1\\) gives one term; repeated factor \\((x+1)^2\\) needs both \\(B/(x+1)\\) and \\(C/(x+1)^2\\) — every power up to the multiplicity." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "1 = A(x + 1)^2 + B(x - 1)(x + 1) + C(x - 1)", explanation: "Multiply both sides by \\((x-1)(x+1)^2\\); the identity must hold for every \\(x\\)." }, { stepNumber: 3, description: "Substitute the roots.", workingLatex: "x = 1:\\;1 = 4A \\Rightarrow A = \\displaystyle\\frac{1}{4};\\quad x = -1:\\;1 = -2C \\Rightarrow C = -\\displaystyle\\frac{1}{2}", explanation: "Each root collapses two of the three terms." }, { stepNumber: 4, description: "Find \\(B\\) by comparing coefficients of \\(x^2\\).", workingLatex: "0 = A + B \\Rightarrow B = -\\displaystyle\\frac{1}{4}", explanation: "The LHS has no \\(x^2\\) term; on the right \\(A(x+1)^2 + B(x-1)(x+1) = (A+B)x^2 + \\ldots\\). With \\(A = 1/4\\), \\(B = -1/4\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{(x - 1)(x + 1)^2} = \\displaystyle\\frac{1/4}{x - 1} - \\displaystyle\\frac{1/4}{x + 1} - \\displaystyle\\frac{1/2}{(x + 1)^2}", explanation: "Substitute \\(A = 1/4, B = -1/4, C = -1/2\\) back." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\frac{1}{4}\\ln|x - 1| - \\displaystyle\\frac{1}{4}\\ln|x + 1| - \\displaystyle\\frac{1}{2}\\!\\int (x+1)^{-2}\\,dx", explanation: "First two terms are direct logs; the last term uses the power rule with \\(n = -2\\)." }, { stepNumber: 7, description: "Finish the last integral.", workingLatex: "-\\displaystyle\\frac{1}{2}\\!\\int (x+1)^{-2}\\,dx = -\\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{(x+1)^{-1}}{-1} = \\displaystyle\\frac{1}{2(x + 1)}", explanation: "\\(\\int (x+1)^{-2}\\,dx = -(x+1)^{-1}\\); the two minus signs combine to a plus." }, { stepNumber: 8, description: "Combine and tidy.", workingLatex: "= \\displaystyle\\frac{1}{4}\\ln\\!\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| + \\displaystyle\\frac{1}{2(x + 1)} + C", explanation: "Merge the two logs using \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 9, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{4}\\ln|x-1| - \\displaystyle\\frac{1}{4}\\ln|x+1| + \\displaystyle\\frac{1}{2(x+1)}\\right] = \\displaystyle\\frac{1/4}{x-1} - \\displaystyle\\frac{1/4}{x+1} - \\displaystyle\\frac{1/2}{(x+1)^2} = \\displaystyle\\frac{1}{(x-1)(x+1)^2}\\;\\checkmark", explanation: "The reciprocal-square term differentiates back via \\(\\displaystyle\\frac{d}{dx}[1/(2(x+1))] = -1/(2(x+1)^2)\\). Recovers the integrand." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{4}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| + \\displaystyle\\frac{1}{2(x + 1)} + C\\)." } },
  { id: "y2in7-057", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 57", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2x + 5}{\\left(x + 1\\right)^2\\left(x - 3\\right)}\\,dx \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{2x + 5}{(x + 1)^2(x - 3)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{(x + 1)^2} + \\displaystyle\\frac{C}{x - 3}", explanation: "Repeated factor \\((x+1)^2\\) needs two terms (one over \\(x+1\\), one over \\((x+1)^2\\)); the distinct factor \\(x-3\\) gives a single term." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "2x + 5 = A(x + 1)(x - 3) + B(x - 3) + C(x + 1)^2", explanation: "Multiply both sides by \\((x+1)^2(x-3)\\)." }, { stepNumber: 3, description: "Substitute the roots.", workingLatex: "x = -1:\\;3 = -4B \\Rightarrow B = -\\displaystyle\\frac{3}{4};\\quad x = 3:\\;11 = 16C \\Rightarrow C = \\displaystyle\\frac{11}{16}", explanation: "Each root collapses two of the three terms, isolating \\(B\\) and \\(C\\)." }, { stepNumber: 4, description: "Find \\(A\\) by comparing coefficients of \\(x^2\\).", workingLatex: "0 = A + C \\Rightarrow A = -\\displaystyle\\frac{11}{16}", explanation: "The LHS has no \\(x^2\\) term; on the right \\(A(x+1)(x-3) + C(x+1)^2\\) contribute \\((A + C)x^2\\). With \\(C = 11/16\\), \\(A = -11/16\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2x + 5}{(x + 1)^2(x - 3)} = -\\displaystyle\\frac{11/16}{x + 1} - \\displaystyle\\frac{3/4}{(x + 1)^2} + \\displaystyle\\frac{11/16}{x - 3}", explanation: "Substitute \\(A = -11/16, B = -3/4, C = 11/16\\) back." }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "-\\displaystyle\\frac{11}{16}\\ln|x + 1| + \\displaystyle\\frac{3}{4(x + 1)} + \\displaystyle\\frac{11}{16}\\ln|x - 3|", explanation: "Logs for the two simple linear terms; the \\(-3/4 \\cdot (x+1)^{-2}\\) term integrates to \\(-\\displaystyle\\frac{3}{4}\\cdot[-(x+1)^{-1}] = \\displaystyle\\frac{3}{4(x+1)}\\)." }, { stepNumber: 7, description: "Combine the logs.", workingLatex: "= \\displaystyle\\frac{11}{16}\\ln\\!\\left|\\displaystyle\\frac{x - 3}{x + 1}\\right| + \\displaystyle\\frac{3}{4(x + 1)} + C", explanation: "Use \\(\\ln a - \\ln b = \\ln(a/b)\\) to tidy the two log terms." }, { stepNumber: 8, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{11}{16}\\ln|x-3| - \\displaystyle\\frac{11}{16}\\ln|x+1| + \\displaystyle\\frac{3}{4(x+1)}\\right] = \\displaystyle\\frac{11/16}{x-3} - \\displaystyle\\frac{11/16}{x+1} - \\displaystyle\\frac{3/4}{(x+1)^2} = \\displaystyle\\frac{2x+5}{(x+1)^2(x-3)}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(\\displaystyle\\frac{11}{16}\\ln\\left|\\displaystyle\\frac{x - 3}{x + 1}\\right| + \\displaystyle\\frac{3}{4(x + 1)} + C\\)." } },
  { id: "y2in7-058", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 58", difficulty: "Standard", questionText: "Find the area under \\(y = \\displaystyle\\frac{1}{x^2 - 1}\\) from \\(x = 2\\) to \\(x = 3\\).", marks: 3, examStyle: true, yearCreated: 2026, tags: ["area"], workedSolution: { steps: [ { stepNumber: 1, description: "Set up the area integral.", workingLatex: "\\text{Area} = \\displaystyle\\int_2^3 \\displaystyle\\frac{1}{x^2 - 1}\\,dx", explanation: "On \\([2,3]\\) the integrand is positive (since \\(x^2 - 1 > 0\\) for \\(x > 1\\)), so the definite integral equals the geometric area between the curve and the \\(x\\)-axis." }, { stepNumber: 2, description: "Decompose the integrand.", workingLatex: "\\displaystyle\\frac{1}{x^2 - 1} = \\displaystyle\\frac{1}{(x - 1)(x + 1)} = \\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1}", explanation: "Standard difference-of-squares factoring; then \\(1 = A(x+1) + B(x-1)\\) gives \\(A = 1/2\\) (at \\(x = 1\\)) and \\(B = -1/2\\) (at \\(x = -1\\))." }, { stepNumber: 3, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{1/2}{x + 1}\\right)dx = \\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{1}{2}\\ln|x + 1| = \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Each piece is a direct log; combine with \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 4, description: "Apply the limits.", workingLatex: "\\left[\\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{x - 1}{x + 1}\\right]_2^3 = \\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{2}{4} - \\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{1}{3}", explanation: "Plug in \\(x = 3\\) and \\(x = 2\\). Both arguments are positive on \\([2,3]\\) so we can drop the modulus bars." }, { stepNumber: 5, description: "Combine the logs.", workingLatex: "= \\displaystyle\\frac{1}{2}\\!\\left(\\ln\\!\\displaystyle\\frac{1}{2} - \\ln\\!\\displaystyle\\frac{1}{3}\\right) = \\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{1/2}{1/3} = \\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{3}{2}", explanation: "\\(\\ln(1/2) - \\ln(1/3) = \\ln((1/2)\\div(1/3)) = \\ln(3/2)\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln\\!\\displaystyle\\frac{x-1}{x+1}\\right] = \\displaystyle\\frac{1}{2}\\!\\left(\\displaystyle\\frac{1}{x-1} - \\displaystyle\\frac{1}{x+1}\\right) = \\displaystyle\\frac{1}{x^2 - 1}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\displaystyle\\frac{3}{2}\\)." } },
  { id: "y2in7-059", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 59", difficulty: "Standard", questionText: "Using partial fractions, prove \\( \\displaystyle\\int \\displaystyle\\frac{1}{1 - x^2}\\,dx = \\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right| + C \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["proof"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "1 - x^2 = (1 - x)(1 + x)", explanation: "Difference of squares — the two linear factors set up the standard distinct-root decomposition." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{1}{(1 - x)(1 + x)} = \\displaystyle\\frac{A}{1 - x} + \\displaystyle\\frac{B}{1 + x}", explanation: "Two distinct linear factors: one constant numerator each." }, { stepNumber: 3, description: "Clear denominators and solve.", workingLatex: "1 = A(1 + x) + B(1 - x);\\quad x = 1:\\;A = \\displaystyle\\frac{1}{2};\\;\\; x = -1:\\;B = \\displaystyle\\frac{1}{2}", explanation: "Substitute the roots of the factors. Each isolates one unknown." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{1 - x^2} = \\displaystyle\\frac{1/2}{1 - x} + \\displaystyle\\frac{1/2}{1 + x}", explanation: "Substitute back. The decomposition is symmetric — both numerators are \\(1/2\\)." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1/2}{1 - x}\\,dx + \\displaystyle\\int \\displaystyle\\frac{1/2}{1 + x}\\,dx = -\\displaystyle\\frac{1}{2}\\ln|1 - x| + \\displaystyle\\frac{1}{2}\\ln|1 + x| + C", explanation: "The first integrand has \\(\\displaystyle\\frac{d}{dx}(1-x) = -1\\), so \\(\\int 1/(1-x)\\,dx = -\\ln|1-x|\\). The second is a direct log." }, { stepNumber: 6, description: "Combine the logs.", workingLatex: "= \\displaystyle\\frac{1}{2}\\bigl(\\ln|1 + x| - \\ln|1 - x|\\bigr) + C = \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right| + C", explanation: "Use \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Conclude.", workingLatex: "\\therefore \\displaystyle\\int \\displaystyle\\frac{1}{1 - x^2}\\,dx = \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right| + C\\quad\\blacksquare", explanation: "Matches the stated identity." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{1 + x}{1 - x}\\right| + C\\). \\(\\blacksquare\\)" } },
  // ── Applied ────
  { id: "y2in7-060", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 60", difficulty: "Challenge", questionText: "Given \\(\\displaystyle\\frac{dP}{dt} = P(10 - P)\\) (logistic), use partial fractions to integrate \\(\\displaystyle\\int \\displaystyle\\frac{1}{P(10 - P)}\\,dP\\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["applied", "differential"], workedSolution: { steps: [ { stepNumber: 1, description: "Why partial fractions here.", workingLatex: "\\displaystyle\\frac{1}{P(10 - P)} \\text{ — proper rational, two distinct linear factors in } P.", explanation: "Separating the logistic ODE \\(dP/dt = P(10-P)\\) gives \\(\\int dP/[P(10-P)] = \\int dt\\). The \\(P\\)-side integral is exactly the partial-fractions set-up below." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{1}{P(10 - P)} = \\displaystyle\\frac{A}{P} + \\displaystyle\\frac{B}{10 - P}", explanation: "Two distinct linear factors in \\(P\\); each contributes a constant numerator." }, { stepNumber: 3, description: "Clear denominators and solve.", workingLatex: "1 = A(10 - P) + BP;\\quad P = 0:\\;1 = 10A \\Rightarrow A = \\displaystyle\\frac{1}{10};\\;\\; P = 10:\\;1 = 10B \\Rightarrow B = \\displaystyle\\frac{1}{10}", explanation: "Cover-up at each root pins down both unknowns." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{P(10 - P)} = \\displaystyle\\frac{1/10}{P} + \\displaystyle\\frac{1/10}{10 - P}", explanation: "Substitute \\(A = B = 1/10\\) back. The symmetric form is no accident — the two factors are symmetric about \\(P = 5\\)." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1/10}{P}\\,dP + \\displaystyle\\int \\displaystyle\\frac{1/10}{10 - P}\\,dP = \\displaystyle\\frac{1}{10}\\ln|P| - \\displaystyle\\frac{1}{10}\\ln|10 - P| + C", explanation: "First term is a direct log; for the second, \\(\\displaystyle\\frac{d}{dP}(10-P) = -1\\), so \\(\\int 1/(10-P)\\,dP = -\\ln|10-P|\\)." }, { stepNumber: 6, description: "Combine the logs.", workingLatex: "= \\displaystyle\\frac{1}{10}\\ln\\!\\left|\\displaystyle\\frac{P}{10 - P}\\right| + C", explanation: "Use \\(\\ln a - \\ln b = \\ln(a/b)\\). This compact form is the one you use when separating the logistic ODE." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dP}\\!\\left[\\displaystyle\\frac{1}{10}\\ln\\!\\left|\\displaystyle\\frac{P}{10 - P}\\right|\\right] = \\displaystyle\\frac{1}{10}\\!\\left(\\displaystyle\\frac{1}{P} + \\displaystyle\\frac{1}{10 - P}\\right) = \\displaystyle\\frac{1}{P(10 - P)}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{10}\\ln\\left|\\displaystyle\\frac{P}{10 - P}\\right| + C\\)." } },
  { id: "y2in7-061", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 61", difficulty: "Standard", questionText: "Show \\( \\displaystyle\\int \\displaystyle\\frac{1}{\\left(x - a\\right)\\left(x - b\\right)}\\,dx = \\displaystyle\\frac{1}{a - b}\\ln\\left|\\displaystyle\\frac{x - a}{x - b}\\right| + C \\) for \\(a \\ne b\\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["proof"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{1}{(x - a)(x - b)} = \\displaystyle\\frac{A}{x - a} + \\displaystyle\\frac{B}{x - b}", explanation: "Two distinct linear factors (we are told \\(a \\ne b\\)); each contributes a constant numerator." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "1 = A(x - b) + B(x - a)", explanation: "Multiply both sides by \\((x-a)(x-b)\\)." }, { stepNumber: 3, description: "Substitute the roots.", workingLatex: "x = a:\\;1 = A(a - b) \\Rightarrow A = \\displaystyle\\frac{1}{a - b};\\quad x = b:\\;1 = B(b - a) \\Rightarrow B = -\\displaystyle\\frac{1}{a - b}", explanation: "Each root collapses one of the two terms. Note \\(B = 1/(b-a) = -1/(a-b)\\)." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{1}{(x - a)(x - b)} = \\displaystyle\\frac{1}{a - b}\\!\\left(\\displaystyle\\frac{1}{x - a} - \\displaystyle\\frac{1}{x - b}\\right)", explanation: "Factor the common \\(1/(a-b)\\) out front for cleaner integration." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{(x - a)(x - b)}\\,dx = \\displaystyle\\frac{1}{a - b}\\bigl(\\ln|x - a| - \\ln|x - b|\\bigr) + C", explanation: "Each bracketed piece is a direct \\(f'/f\\) log integral." }, { stepNumber: 6, description: "Combine the logs.", workingLatex: "= \\displaystyle\\frac{1}{a - b}\\ln\\!\\left|\\displaystyle\\frac{x - a}{x - b}\\right| + C\\quad\\blacksquare", explanation: "Use \\(\\ln a - \\ln b = \\ln(a/b)\\). Matches the stated identity." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{a - b}\\ln\\left|\\displaystyle\\frac{x - a}{x - b}\\right| + C\\). \\(\\blacksquare\\)" } },
  { id: "y2in7-062", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 62", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{4x - 1}{\\left(x - 1\\right)\\left(x + 2\\right)\\left(x - 3\\right)}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{4x - 1}{(x - 1)(x + 2)(x - 3)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x + 2} + \\displaystyle\\frac{C}{x - 3}", explanation: "Three distinct linear factors — one constant numerator each. The rational is proper (degree 1 over degree 3)." }, { stepNumber: 2, description: "Use the cover-up rule for each constant.", workingLatex: "A = \\displaystyle\\frac{4(1) - 1}{(1 + 2)(1 - 3)} = \\displaystyle\\frac{3}{-6} = -\\displaystyle\\frac{1}{2}", explanation: "Cover \\(x - 1\\) and evaluate the rest at \\(x = 1\\): numerator \\(= 3\\), other denominator factors \\(= (3)(-2) = -6\\)." }, { stepNumber: 3, description: "Cover-up for \\(B\\).", workingLatex: "B = \\displaystyle\\frac{4(-2) - 1}{(-2 - 1)(-2 - 3)} = \\displaystyle\\frac{-9}{(-3)(-5)} = \\displaystyle\\frac{-9}{15} = -\\displaystyle\\frac{3}{5}", explanation: "Cover \\(x + 2\\) and evaluate the rest at \\(x = -2\\): numerator \\(= -9\\), other factors \\(= 15\\)." }, { stepNumber: 4, description: "Cover-up for \\(C\\).", workingLatex: "C = \\displaystyle\\frac{4(3) - 1}{(3 - 1)(3 + 2)} = \\displaystyle\\frac{11}{(2)(5)} = \\displaystyle\\frac{11}{10}", explanation: "Cover \\(x - 3\\) and evaluate the rest at \\(x = 3\\): numerator \\(= 11\\), other factors \\(= 10\\)." }, { stepNumber: 5, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{4x - 1}{(x - 1)(x + 2)(x - 3)} = -\\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{3/5}{x + 2} + \\displaystyle\\frac{11/10}{x - 3}", explanation: "Substitute the three constants back. Quick sanity check at \\(x = 0\\): LHS \\(= -1/((-1)(2)(-3)) = -1/6\\); RHS \\(= 1/2 - 3/10 - 11/30 = 15/30 - 9/30 - 11/30 = -5/30 = -1/6\\). \\(\\checkmark\\)" }, { stepNumber: 6, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left(-\\displaystyle\\frac{1/2}{x - 1} - \\displaystyle\\frac{3/5}{x + 2} + \\displaystyle\\frac{11/10}{x - 3}\\right)dx = -\\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{3}{5}\\ln|x + 2| + \\displaystyle\\frac{11}{10}\\ln|x - 3| + C", explanation: "Each term is in clean \\(f'/f\\) form (the derivative of each linear factor is \\(1\\)), giving a log times the constant numerator." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\displaystyle\\frac{1}{2}\\ln|x-1| - \\displaystyle\\frac{3}{5}\\ln|x+2| + \\displaystyle\\frac{11}{10}\\ln|x-3|\\right] = -\\displaystyle\\frac{1/2}{x-1} - \\displaystyle\\frac{3/5}{x+2} + \\displaystyle\\frac{11/10}{x-3} = \\displaystyle\\frac{4x - 1}{(x-1)(x+2)(x-3)}\\;\\checkmark", explanation: "Recombining over the common denominator recovers the integrand exactly — antiderivative verified." } ], finalAnswer: "\\(-\\displaystyle\\frac{1}{2}\\ln|x - 1| - \\displaystyle\\frac{3}{5}\\ln|x + 2| + \\displaystyle\\frac{11}{10}\\ln|x - 3| + C\\)." } },
  { id: "y2in7-063", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 63", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{3}{9x^2 - 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "9x^2 - 1 = (3x - 1)(3x + 1)", explanation: "Difference of squares: \\((3x)^2 - 1^2\\)." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{3}{(3x - 1)(3x + 1)} = \\displaystyle\\frac{A}{3x - 1} + \\displaystyle\\frac{B}{3x + 1}", explanation: "Two distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Clear denominators and solve.", workingLatex: "3 = A(3x + 1) + B(3x - 1);\\quad x = \\displaystyle\\frac{1}{3}:\\;3 = 2A \\Rightarrow A = \\displaystyle\\frac{3}{2};\\;\\; x = -\\displaystyle\\frac{1}{3}:\\;3 = -2B \\Rightarrow B = -\\displaystyle\\frac{3}{2}", explanation: "Substitute the roots of \\(3x - 1\\) and \\(3x + 1\\) respectively." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{3}{9x^2 - 1} = \\displaystyle\\frac{3/2}{3x - 1} - \\displaystyle\\frac{3/2}{3x + 1}", explanation: "Substitute \\(A = 3/2, B = -3/2\\) back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{3/2}{3x - 1} - \\displaystyle\\frac{3/2}{3x + 1}\\right)dx = \\displaystyle\\frac{3}{2}\\cdot\\displaystyle\\frac{1}{3}\\ln|3x - 1| - \\displaystyle\\frac{3}{2}\\cdot\\displaystyle\\frac{1}{3}\\ln|3x + 1| + C", explanation: "Each denominator has derivative \\(3\\); \\(\\int 1/(3x\\pm 1)\\,dx = (1/3)\\ln|3x\\pm 1|\\)." }, { stepNumber: 6, description: "Tidy.", workingLatex: "= \\displaystyle\\frac{1}{2}\\ln|3x - 1| - \\displaystyle\\frac{1}{2}\\ln|3x + 1| + C = \\displaystyle\\frac{1}{2}\\ln\\!\\left|\\displaystyle\\frac{3x - 1}{3x + 1}\\right| + C", explanation: "Combine constants \\(\\displaystyle\\frac{3}{2}\\cdot\\displaystyle\\frac{1}{3} = \\displaystyle\\frac{1}{2}\\); merge logs with \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln|3x-1| - \\displaystyle\\frac{1}{2}\\ln|3x+1|\\right] = \\displaystyle\\frac{3/2}{3x-1} - \\displaystyle\\frac{3/2}{3x+1} = \\displaystyle\\frac{3}{9x^2 - 1}\\;\\checkmark", explanation: "Recombine over the common denominator: \\((3/2)\\cdot[(3x+1)-(3x-1)]/(9x^2-1) = 3/(9x^2-1)\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln\\left|\\displaystyle\\frac{3x - 1}{3x + 1}\\right| + C\\)." } },
  { id: "y2in7-064", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 64", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{2x - 5}{x^2 - 3x + 2}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 3x + 2 = (x - 1)(x - 2)", explanation: "Roots of the quadratic are \\(1\\) and \\(2\\) (sum \\(3\\), product \\(2\\))." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{2x - 5}{(x - 1)(x - 2)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{B}{x - 2}", explanation: "Two distinct linear factors." }, { stepNumber: 3, description: "Clear denominators and solve.", workingLatex: "2x - 5 = A(x - 2) + B(x - 1);\\quad x = 1:\\;-3 = -A \\Rightarrow A = 3;\\;\\; x = 2:\\;-1 = B \\Rightarrow B = -1", explanation: "Substitute the roots." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2x - 5}{x^2 - 3x + 2} = \\displaystyle\\frac{3}{x - 1} - \\displaystyle\\frac{1}{x - 2}", explanation: "Substitute \\(A = 3, B = -1\\) back." }, { stepNumber: 5, description: "Integrate each piece.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{3}{x - 1} - \\displaystyle\\frac{1}{x - 2}\\right)dx = 3\\ln|x - 1| - \\ln|x - 2| + C", explanation: "Each piece is in clean \\(f'/f\\) form with \\(f'(x) = 1\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[3\\ln|x-1| - \\ln|x-2|\\right] = \\displaystyle\\frac{3}{x-1} - \\displaystyle\\frac{1}{x-2} = \\displaystyle\\frac{3(x-2) - (x-1)}{(x-1)(x-2)} = \\displaystyle\\frac{2x - 5}{x^2 - 3x + 2}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(3\\ln|x - 1| - \\ln|x - 2| + C\\)." } },
  { id: "y2in7-065", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 65", difficulty: "Foundation", questionText: "Verify by differentiation that \\( \\displaystyle\\frac{d}{dx}\\left(\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|\\right) = \\displaystyle\\frac{2}{x^2 - 1} \\).", marks: 2, examStyle: false, yearCreated: 2026, tags: ["verify"], workedSolution: { steps: [ { stepNumber: 1, description: "Split the log of a quotient.", workingLatex: "\\ln\\!\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| = \\ln|x - 1| - \\ln|x + 1|", explanation: "Using \\(\\ln(a/b) = \\ln a - \\ln b\\). Easier to differentiate as two separate logs than as a quotient inside a log." }, { stepNumber: 2, description: "Differentiate each term.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\bigl[\\ln|x - 1|\\bigr] = \\displaystyle\\frac{1}{x - 1};\\quad \\displaystyle\\frac{d}{dx}\\!\\bigl[\\ln|x + 1|\\bigr] = \\displaystyle\\frac{1}{x + 1}", explanation: "Standard derivative \\(\\displaystyle\\frac{d}{dx}\\ln|f(x)| = f'(x)/f(x)\\); here \\(f'(x) = 1\\) in each case." }, { stepNumber: 3, description: "Subtract and combine.", workingLatex: "\\displaystyle\\frac{1}{x - 1} - \\displaystyle\\frac{1}{x + 1} = \\displaystyle\\frac{(x + 1) - (x - 1)}{(x - 1)(x + 1)} = \\displaystyle\\frac{2}{x^2 - 1}", explanation: "Common-denominator subtraction: the numerator simplifies to \\(2\\), and \\((x-1)(x+1) = x^2 - 1\\)." }, { stepNumber: 4, description: "Conclude.", workingLatex: "\\therefore \\displaystyle\\frac{d}{dx}\\!\\left(\\ln\\!\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|\\right) = \\displaystyle\\frac{2}{x^2 - 1}\\quad\\blacksquare", explanation: "Matches the stated identity. Equivalently, \\(\\int 2/(x^2 - 1)\\,dx = \\ln|(x-1)/(x+1)| + C\\), which is the integration counterpart." } ], finalAnswer: "Confirmed: \\(\\displaystyle\\frac{d}{dx}\\ln\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right| = \\displaystyle\\frac{2}{x^2 - 1}\\). \\(\\blacksquare\\)" } },
  { id: "y2in7-066", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 66", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2 + x}{\\left(x + 1\\right)\\left(x^2 + 1\\right)}\\,dx \\) (outside pure A-level but useful).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot a common factor in the numerator.", workingLatex: "x^2 + x = x(x + 1)", explanation: "Before launching into the full partial-fractions template, always check whether the numerator shares a factor with the denominator — it can collapse the problem entirely." }, { stepNumber: 2, description: "Cancel the common factor.", workingLatex: "\\displaystyle\\frac{x^2 + x}{(x + 1)(x^2 + 1)} = \\displaystyle\\frac{x(x + 1)}{(x + 1)(x^2 + 1)} = \\displaystyle\\frac{x}{x^2 + 1}", explanation: "The factor \\(x + 1\\) cancels, reducing a three-term partial-fractions exercise to a single reverse-chain log." }, { stepNumber: 3, description: "Cross-check with the formal template.", workingLatex: "\\displaystyle\\frac{x}{x^2 + 1} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{Bx + C}{x^2 + 1}", explanation: "If we hadn't spotted the cancellation, we'd decompose with a linear numerator over the irreducible quadratic. Solving (e.g. multiply through and compare coefficients) gives \\(A = 0, B = 1, C = 0\\) — recovering the same simplified form." }, { stepNumber: 4, description: "Spot the \\(f'/f\\) pattern.", workingLatex: "\\text{Numerator } x = \\displaystyle\\frac{1}{2}\\,\\displaystyle\\frac{d}{dx}(x^2 + 1)", explanation: "The derivative of the denominator \\(x^2 + 1\\) is \\(2x\\); the numerator is half of that. Reverse-chain log territory." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 + 1}\\,dx = \\displaystyle\\frac{1}{2}\\displaystyle\\int \\displaystyle\\frac{2x}{x^2 + 1}\\,dx = \\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C", explanation: "Pull out a \\(1/2\\) to line the numerator up with \\(f'\\), then apply \\(\\int f'/f\\,dx = \\ln|f|\\). Modulus bars drop because \\(x^2 + 1 \\ge 1 > 0\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\displaystyle\\frac{1}{2}\\ln(x^2 + 1)\\right] = \\displaystyle\\frac{1}{2}\\cdot\\displaystyle\\frac{2x}{x^2 + 1} = \\displaystyle\\frac{x}{x^2 + 1} = \\displaystyle\\frac{x^2 + x}{(x + 1)(x^2 + 1)}\\;\\checkmark", explanation: "Recovers the (simplified, then original) integrand — antiderivative verified." } ], finalAnswer: "\\(\\displaystyle\\frac{1}{2}\\ln(x^2 + 1) + C\\)." } },
  { id: "y2in7-067", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 67", difficulty: "Standard", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{6}{x^2 - 9}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor the denominator.", workingLatex: "x^2 - 9 = (x - 3)(x + 3)", explanation: "Difference of squares." }, { stepNumber: 2, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{6}{(x - 3)(x + 3)} = \\displaystyle\\frac{A}{x - 3} + \\displaystyle\\frac{B}{x + 3}", explanation: "Two distinct linear factors — constant numerators." }, { stepNumber: 3, description: "Clear denominators and solve.", workingLatex: "6 = A(x + 3) + B(x - 3);\\quad x = 3:\\;6 = 6A \\Rightarrow A = 1;\\;\\; x = -3:\\;6 = -6B \\Rightarrow B = -1", explanation: "Substitute the roots." }, { stepNumber: 4, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{6}{x^2 - 9} = \\displaystyle\\frac{1}{x - 3} - \\displaystyle\\frac{1}{x + 3}", explanation: "Substitute \\(A = 1, B = -1\\) back." }, { stepNumber: 5, description: "Integrate.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{1}{x - 3} - \\displaystyle\\frac{1}{x + 3}\\right)dx = \\ln|x - 3| - \\ln|x + 3| + C = \\ln\\!\\left|\\displaystyle\\frac{x - 3}{x + 3}\\right| + C", explanation: "Each piece is a direct log; combine with \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 6, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\ln\\!\\left|\\displaystyle\\frac{x-3}{x+3}\\right| = \\displaystyle\\frac{1}{x-3} - \\displaystyle\\frac{1}{x+3} = \\displaystyle\\frac{(x+3) - (x-3)}{x^2 - 9} = \\displaystyle\\frac{6}{x^2 - 9}\\;\\checkmark", explanation: "Recovers the integrand." } ], finalAnswer: "\\(\\ln\\left|\\displaystyle\\frac{x - 3}{x + 3}\\right| + C\\)." } },
  { id: "y2in7-068", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 68", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_2^3 \\displaystyle\\frac{4}{x^2 - 1}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "Factor and decompose.", workingLatex: "\\displaystyle\\frac{4}{x^2 - 1} = \\displaystyle\\frac{4}{(x - 1)(x + 1)} = \\displaystyle\\frac{2}{x - 1} - \\displaystyle\\frac{2}{x + 1}", explanation: "Difference of squares, then \\(4 = A(x+1) + B(x-1)\\) gives \\(A = 2\\) (at \\(x = 1\\)) and \\(B = -2\\) (at \\(x = -1\\))." }, { stepNumber: 2, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int\\!\\left(\\displaystyle\\frac{2}{x - 1} - \\displaystyle\\frac{2}{x + 1}\\right)dx = 2\\ln|x - 1| - 2\\ln|x + 1| = 2\\ln\\!\\left|\\displaystyle\\frac{x - 1}{x + 1}\\right|", explanation: "Two direct logs combined via \\(\\ln a - \\ln b = \\ln(a/b)\\)." }, { stepNumber: 3, description: "Apply the upper limit.", workingLatex: "\\left.2\\ln\\!\\displaystyle\\frac{x - 1}{x + 1}\\right|_{x = 3} = 2\\ln\\!\\displaystyle\\frac{2}{4} = 2\\ln\\!\\displaystyle\\frac{1}{2}", explanation: "On \\([2,3]\\) the argument is positive so the bars drop." }, { stepNumber: 4, description: "Apply the lower limit.", workingLatex: "\\left.2\\ln\\!\\displaystyle\\frac{x - 1}{x + 1}\\right|_{x = 2} = 2\\ln\\!\\displaystyle\\frac{1}{3}", explanation: "Same convention." }, { stepNumber: 5, description: "Subtract.", workingLatex: "\\displaystyle\\int_2^3 \\displaystyle\\frac{4}{x^2 - 1}\\,dx = 2\\ln\\!\\displaystyle\\frac{1}{2} - 2\\ln\\!\\displaystyle\\frac{1}{3} = 2\\!\\left(\\ln\\!\\displaystyle\\frac{1}{2} - \\ln\\!\\displaystyle\\frac{1}{3}\\right)", explanation: "Pull the common factor of \\(2\\) out for tidier merging." }, { stepNumber: 6, description: "Combine the logs.", workingLatex: "= 2\\ln\\!\\displaystyle\\frac{1/2}{1/3} = 2\\ln\\!\\displaystyle\\frac{3}{2}", explanation: "\\(\\ln(1/2) - \\ln(1/3) = \\ln((1/2)\\cdot 3) = \\ln(3/2)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[2\\ln\\!\\left|\\displaystyle\\frac{x-1}{x+1}\\right|\\right] = 2\\!\\left(\\displaystyle\\frac{1}{x-1} - \\displaystyle\\frac{1}{x+1}\\right) = \\displaystyle\\frac{4}{x^2 - 1}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(2\\ln\\displaystyle\\frac{3}{2}\\)." } },
  { id: "y2in7-069", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 69", difficulty: "Standard", questionText: "Evaluate \\( \\displaystyle\\int_0^1 \\displaystyle\\frac{2x + 1}{\\left(x + 1\\right)\\left(x + 2\\right)}\\,dx \\).", marks: 4, examStyle: true, yearCreated: 2026, tags: ["definite"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{2x + 1}{(x + 1)(x + 2)} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{x + 2}", explanation: "Two distinct linear factors — constant numerators each. Note degree(num) < degree(den), so already proper." }, { stepNumber: 2, description: "Clear denominators and solve.", workingLatex: "2x + 1 = A(x + 2) + B(x + 1);\\quad x = -1:\\;-1 = A;\\;\\; x = -2:\\;-3 = -B \\Rightarrow B = 3", explanation: "Cover-up at each root pins down the two unknowns." }, { stepNumber: 3, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{2x + 1}{(x + 1)(x + 2)} = -\\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{3}{x + 2}", explanation: "Substitute \\(A = -1, B = 3\\) back." }, { stepNumber: 4, description: "Find the antiderivative.", workingLatex: "\\displaystyle\\int\\!\\left(-\\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{3}{x + 2}\\right)dx = -\\ln|x + 1| + 3\\ln|x + 2|", explanation: "Two direct \\(f'/f\\) logs." }, { stepNumber: 5, description: "Apply the limits.", workingLatex: "\\left[-\\ln|x + 1| + 3\\ln|x + 2|\\right]_0^1 = \\bigl(-\\ln 2 + 3\\ln 3\\bigr) - \\bigl(-\\ln 1 + 3\\ln 2\\bigr)", explanation: "Plug in \\(x = 1\\) and \\(x = 0\\); recall \\(\\ln 1 = 0\\). All arguments are positive so bars drop." }, { stepNumber: 6, description: "Simplify.", workingLatex: "= -\\ln 2 + 3\\ln 3 - 3\\ln 2 = 3\\ln 3 - 4\\ln 2 = \\ln\\!\\displaystyle\\frac{27}{16}", explanation: "Collect like log terms: \\(-\\ln 2 - 3\\ln 2 = -4\\ln 2\\). Combine to a single log: \\(3\\ln 3 - 4\\ln 2 = \\ln(3^3/2^4) = \\ln(27/16)\\)." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[-\\ln|x+1| + 3\\ln|x+2|\\right] = -\\displaystyle\\frac{1}{x+1} + \\displaystyle\\frac{3}{x+2} = \\displaystyle\\frac{-(x+2) + 3(x+1)}{(x+1)(x+2)} = \\displaystyle\\frac{2x + 1}{(x+1)(x+2)}\\;\\checkmark", explanation: "Recovers the integrand — antiderivative verified." } ], finalAnswer: "\\(3\\ln 3 - 4\\ln 2 = \\ln\\displaystyle\\frac{27}{16}\\)." } },
  { id: "y2in7-070", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 70", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{5x + 6}{\\left(x - 1\\right)\\left(x^2 + 2\\right)}\\,dx \\).", marks: 6, examStyle: true, yearCreated: 2026, tags: ["partial fractions"], workedSolution: { steps: [ { stepNumber: 1, description: "State the decomposition template.", workingLatex: "\\displaystyle\\frac{5x + 6}{(x - 1)(x^2 + 2)} = \\displaystyle\\frac{A}{x - 1} + \\displaystyle\\frac{Bx + C}{x^2 + 2}", explanation: "Linear factor \\(x-1\\) gives a constant numerator; the irreducible quadratic \\(x^2 + 2\\) (discriminant \\(-8 < 0\\)) requires a linear numerator \\(Bx + C\\)." }, { stepNumber: 2, description: "Clear denominators.", workingLatex: "5x + 6 = A(x^2 + 2) + (Bx + C)(x - 1)", explanation: "Multiply both sides by \\((x-1)(x^2 + 2)\\); the identity must hold for every \\(x\\)." }, { stepNumber: 3, description: "Find \\(A\\) by substituting the linear root.", workingLatex: "x = 1:\\;11 = 3A \\Rightarrow A = \\displaystyle\\frac{11}{3}", explanation: "Only the linear-factor root collapses a term cleanly; the quadratic has no real roots." }, { stepNumber: 4, description: "Find \\(B\\) and \\(C\\) by comparing coefficients.", workingLatex: "\\text{Expand RHS: }(A + B)x^2 + (-B + C)x + (2A - C)", explanation: "Expand \\(A(x^2+2) + (Bx+C)(x-1) = Ax^2 + 2A + Bx^2 - Bx + Cx - C\\) and collect like terms." }, { stepNumber: 5, description: "Solve the coefficient equations.", workingLatex: "x^2:\\;A + B = 0 \\Rightarrow B = -\\displaystyle\\frac{11}{3};\\quad x^1:\\;-B + C = 5 \\Rightarrow C = 5 - \\displaystyle\\frac{11}{3} = \\displaystyle\\frac{4}{3}", explanation: "Match coefficients to the LHS \\(5x + 6\\) (which has no \\(x^2\\) term). Also check the constant: \\(2A - C = 22/3 - 4/3 = 18/3 = 6\\). \\(\\checkmark\\)" }, { stepNumber: 6, description: "Write the decomposition.", workingLatex: "\\displaystyle\\frac{5x + 6}{(x - 1)(x^2 + 2)} = \\displaystyle\\frac{11/3}{x - 1} + \\displaystyle\\frac{-(11/3)x + 4/3}{x^2 + 2}", explanation: "Substitute \\(A = 11/3, B = -11/3, C = 4/3\\) back." }, { stepNumber: 7, description: "Integrate the linear-factor piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{11/3}{x - 1}\\,dx = \\displaystyle\\frac{11}{3}\\ln|x - 1|", explanation: "Direct \\(f'/f\\) log." }, { stepNumber: 8, description: "Split the quadratic-factor piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{-(11/3)x + 4/3}{x^2 + 2}\\,dx = -\\displaystyle\\frac{11}{3}\\!\\int \\displaystyle\\frac{x}{x^2 + 2}\\,dx + \\displaystyle\\frac{4}{3}\\!\\int \\displaystyle\\frac{1}{x^2 + 2}\\,dx", explanation: "Linearity. The \\(x/(x^2+2)\\) integral is reverse-chain log; the \\(1/(x^2+2)\\) integral is the arctan template." }, { stepNumber: 9, description: "Evaluate the two sub-integrals.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x}{x^2 + 2}\\,dx = \\displaystyle\\frac{1}{2}\\ln(x^2 + 2);\\quad \\displaystyle\\int \\displaystyle\\frac{1}{x^2 + 2}\\,dx = \\displaystyle\\frac{1}{\\sqrt{2}}\\arctan\\!\\displaystyle\\frac{x}{\\sqrt{2}}", explanation: "The first uses \\(\\int f'/f = \\ln|f|\\) with a \\(1/2\\) factor (since \\(f' = 2x\\)); the second is \\(\\int 1/(x^2 + a^2)\\,dx = (1/a)\\arctan(x/a)\\) with \\(a = \\sqrt{2}\\)." }, { stepNumber: 10, description: "Assemble and tidy.", workingLatex: "= \\displaystyle\\frac{11}{3}\\ln|x - 1| - \\displaystyle\\frac{11}{6}\\ln(x^2 + 2) + \\displaystyle\\frac{4}{3\\sqrt{2}}\\arctan\\!\\displaystyle\\frac{x}{\\sqrt{2}} + C = \\displaystyle\\frac{11}{3}\\ln|x - 1| - \\displaystyle\\frac{11}{6}\\ln(x^2 + 2) + \\displaystyle\\frac{2\\sqrt{2}}{3}\\arctan\\!\\displaystyle\\frac{x}{\\sqrt{2}} + C", explanation: "Combine constants: \\(-(11/3)\\cdot(1/2) = -11/6\\); \\((4/3)\\cdot(1/\\sqrt 2) = 4/(3\\sqrt 2) = 4\\sqrt 2/6 = 2\\sqrt 2/3\\) after rationalising. Bars drop on \\(\\ln(x^2 + 2)\\) because \\(x^2 + 2 \\ge 2 > 0\\)." } ], finalAnswer: "\\(\\displaystyle\\frac{11}{3}\\ln|x - 1| - \\displaystyle\\frac{11}{6}\\ln(x^2 + 2) + \\displaystyle\\frac{2\\sqrt{2}}{3}\\arctan\\displaystyle\\frac{x}{\\sqrt{2}} + C\\)." } },
  { id: "y2in7-071", topicRef: "y2in7", topicTitle: "Partial Fractions in Integration 71", difficulty: "Challenge", questionText: "Find \\( \\displaystyle\\int \\displaystyle\\frac{x^2 + 2x + 3}{\\left(x + 1\\right)^3}\\,dx \\).", marks: 5, examStyle: true, yearCreated: 2026, tags: ["partial fractions", "repeated"], workedSolution: { steps: [ { stepNumber: 1, description: "Spot a smart rewrite of the numerator.", workingLatex: "x^2 + 2x + 3 = (x^2 + 2x + 1) + 2 = (x + 1)^2 + 2", explanation: "Completing the square inside the numerator makes the matching with the cubed denominator transparent — no need for a full \\(A/(x+1) + B/(x+1)^2 + C/(x+1)^3\\) decomposition." }, { stepNumber: 2, description: "Split the integrand.", workingLatex: "\\displaystyle\\frac{x^2 + 2x + 3}{(x + 1)^3} = \\displaystyle\\frac{(x + 1)^2}{(x + 1)^3} + \\displaystyle\\frac{2}{(x + 1)^3} = \\displaystyle\\frac{1}{x + 1} + \\displaystyle\\frac{2}{(x + 1)^3}", explanation: "Cancel \\((x+1)^2\\) against two of the three factors in the denominator of the first piece. The result is already in clean partial-fractions form." }, { stepNumber: 3, description: "Cross-check via the formal template.", workingLatex: "\\displaystyle\\frac{x^2 + 2x + 3}{(x + 1)^3} = \\displaystyle\\frac{A}{x + 1} + \\displaystyle\\frac{B}{(x + 1)^2} + \\displaystyle\\frac{C}{(x + 1)^3}", explanation: "Solving \\(x^2 + 2x + 3 = A(x+1)^2 + B(x+1) + C\\) by expanding gives \\(A = 1, B = 0, C = 2\\) — confirms the shortcut above." }, { stepNumber: 4, description: "Integrate the first piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{1}{x + 1}\\,dx = \\ln|x + 1|", explanation: "Direct \\(f'/f\\) log." }, { stepNumber: 5, description: "Integrate the second piece.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{2}{(x + 1)^3}\\,dx = 2\\!\\int (x + 1)^{-3}\\,dx = 2\\cdot\\displaystyle\\frac{(x + 1)^{-2}}{-2} = -\\displaystyle\\frac{1}{(x + 1)^2}", explanation: "Power rule with \\(n = -3\\): new index \\(-2\\); divide by \\(-2\\)." }, { stepNumber: 6, description: "Combine.", workingLatex: "\\displaystyle\\int \\displaystyle\\frac{x^2 + 2x + 3}{(x + 1)^3}\\,dx = \\ln|x + 1| - \\displaystyle\\frac{1}{(x + 1)^2} + C", explanation: "Sum the two antiderivatives and add the constant of integration." }, { stepNumber: 7, description: "Differentiation check.", workingLatex: "\\displaystyle\\frac{d}{dx}\\!\\left[\\ln|x+1| - \\displaystyle\\frac{1}{(x+1)^2}\\right] = \\displaystyle\\frac{1}{x+1} + \\displaystyle\\frac{2}{(x+1)^3} = \\displaystyle\\frac{(x+1)^2 + 2}{(x+1)^3} = \\displaystyle\\frac{x^2 + 2x + 3}{(x+1)^3}\\;\\checkmark", explanation: "Recombining over the common denominator \\((x+1)^3\\) recovers the integrand exactly — antiderivative verified." } ], finalAnswer: "\\(\\ln|x + 1| - \\displaystyle\\frac{1}{(x + 1)^2} + C\\)." } },
];
